const u=(body,good,bad,explanation,hint)=>({type:'multi',title:'Selecciona las dos válidas',body,options:[good[0],bad[0],good[1],bad[1]].map(text=>({text})),answers:[0,2],explanation,hint});
const o=(body,items,explanation,hint)=>({type:'order',title:'Ordena el proceso',body,items:[items[2],items[0],items[1]],answer:[1,2,0],explanation,hint});
const b=(title,body,quiz,figure)=>({title,body,quiz,figure});
const ex=(prompt,a,b)=>({prompt,options:[{label:a[0],title:a[0],body:a[1]},{label:b[0],title:b[0],body:b[1]}]});
