const companyIcons={inditex:'store',ti:'cpu',arm:'puzzle',costco:'store',svb:'landmark',nvda:'cpu',berkshire:'briefcase-business',adobe:'palette',unilever:'shopping-basket',cat:'factory',msft:'server',bt:'network',lvmh:'gem',boeing:'plane',grid:'network',visa:'credit-card',alphabet:'server',ge:'settings',wells:'landmark',airbnb:'house',shell:'fuel',prologis:'warehouse',novo:'pill'};
function add(num,key,title,fact,goals,blocks,explore){
 const [company,period,sourceTitle,url]=sources[key];
 blocks[0].body=`${fact}\n\n${blocks[0].body}`;
 blocks[0].figure??=flow(paths[num]);
 blocks[2].explore=explore;
 const steps=blocks.flatMap((v,i)=>[{type:'learn',title:v.title,body:v.body,visual:'none',figure:v.figure,explore:v.explore,takeaway:goals[Math.min(i,goals.length-1)]},v.quiz]);
 // Rotate choices deterministically; avoid training the user to select the first answer.
 for(const [i,s] of steps.entries()){
  if(s.type==='choice'&&((num+i)%2)){s.options.reverse();s.answer=s.options.length-1;}
  if(s.type==='multi'){
   const permutation=[[0,2,1,3],[1,3,0,2],[2,1,3,0]][num%3],oldAnswers=s.answers;
   s.options=permutation.map(j=>s.options[j]);s.answers=permutation.flatMap((j,k)=>oldAnswers.includes(j)?[k]:[]);
  }
  if(s.type==='order'){
   const logical=s.answer.map(j=>s.items[j]),permutation=[[2,0,1],[1,2,0],[1,0,2]][num%3];
   s.items=permutation.map(j=>logical[j]);s.answer=logical.map((_,j)=>permutation.indexOf(j));
  }
 }
 cases.push({id:`stocks-v2-${num}`,revision:'cases-2026-10',track:'stocks',world:44+num,lessonIds:Array.from({length:10},(_,i)=>(44+num)*10+i),learningGoals:goals,title:`${company}: ${title}`,company,period,summary:goals.join(' · '),minutes:12,cover:{icon:companyIcons[key],color:['#358b75','#497aad','#966cb5','#b37937','#357e86'][num%5]},sources:[{title:sourceTitle,url}],takeaway:goals.join(' '),steps});
}

// Each company fact above was checked in the linked primary publication on 2026-10-09.
// Below, every exercise uses an explicitly fictional miniature unless identified as published data.
add(1,'inditex','ser dueño de una parte, no de una tienda','Las cuentas de Inditex de 2024 describen una sola clase de acciones, con los mismos derechos de voto y de dividendo.', ['Distinguir propiedad, empleo y compra de productos.','Calcular una participación y reconocer sus límites.'],[
b('Tres relaciones distintas con la empresa','Comprar una prenda te convierte en cliente. Trabajar en una tienda te convierte en empleado. Comprar una acción te convierte en propietario de una pequeña parte de la sociedad. Son relaciones distintas: ninguna implica automáticamente las otras. Puedes ser accionista sin trabajar allí y sin poder decidir el precio de una prenda. La gestión diaria corresponde a quienes dirigen el negocio.',m('En estas situaciones imaginadas, ¿qué relación crea cada operación?', [['Lucía compra una camiseta','Clienta'],['Raúl compra acciones','Accionista'],['Nora firma un contrato de trabajo','Empleada']],'El objeto de la compra o del contrato determina la relación, no cuánto te guste la marca.','Piensa qué recibe cada persona.')),
b('La parte depende del total','Para entender el porcentaje que posees, divide tus acciones entre todas las acciones de la misma clase y multiplica por cien. Usaremos una empresa simplificada, no el número real de acciones de Inditex. Si todos tienen los mismos derechos por acción, poseer más acciones da más participación. El precio que pagaste no cambia ese porcentaje: importa cuántas tienes respecto al total.',n('Empresa simulada: hay 200 acciones iguales. Compras 8. ¿Qué porcentaje de la empresa posees?',4,'%','8 ÷ 200 × 100 = 4 %. El precio de compra no entra en esta cuenta.','Divide tu número de acciones entre el total.'),table([['Acciones totales','200'],['Acciones compradas','8']])) ,
b('Participar no es mandar en solitario','Tener una acción puede dar derecho a votar en determinadas decisiones y a recibir un reparto si se acuerda. No te permite retirar dinero de la caja ni exigir un sueldo. Tampoco es un préstamo con devolución asegurada. Para esta práctica compramos acciones con dinero propio, sin pedir prestado: si el negocio fracasa, podemos perder lo invertido, aunque no hayamos trabajado ni tomado decisiones en él.',q('Una accionista del ejemplo posee el 4 % y pide que le entreguen el 4 % de la caja ese mismo día. ¿Qué responderías?','Su participación no le permite retirar libremente ese dinero.','La empresa debe entregárselo por ser copropietaria.','Los recursos siguen perteneciendo a la sociedad. Un reparto requiere la decisión y las condiciones correspondientes.','Distingue ser propietario de disponer personalmente de la caja.'))
],ex('¿Qué cambia al relacionarte con la empresa?',['Comprar un producto','Recibes ese producto. No adquieres por ello una parte del negocio.'],['Comprar una acción','Adquieres una participación con derechos y riesgos. No recibes un puesto de trabajo.']));

add(2,'ti','sumar el precio y el dinero cobrado','Texas Instruments informó de dividendos y recompras de acciones en sus resultados de 2024.', ['Separar cambio de precio y dividendos.','Calcular el resultado total después de comisiones.'],[
b('El dividendo forma parte del resultado','Un dividendo es dinero que la empresa acuerda repartir por cada acción. Para calcular lo ganado no basta con mirar el precio final: también cuentan los cobros recibidos y los costes. Las recompras que hace la empresa no son un dividendo que todos los inversores ingresen automáticamente. Aquí practicaremos con una inversión imaginada; sus precios y dividendos no reproducen una operación histórica de Texas Instruments.',q('En una inversión simulada compras por 100 €, vendes por 100 € y cobras 5 € de dividendo, sin costes. ¿Cómo describirías el resultado?','Has ganado dinero aunque el precio no haya cambiado.','El resultado es cero porque compra y venta tienen el mismo precio.','El dividendo añade un cobro al resultado del precio.','Incluye los pagos recibidos mientras tenías la acción.')),
b('Reconstruye todas las entradas y salidas','El resultado en euros se obtiene sumando lo cobrado al vender y los dividendos, y restando lo pagado al comprar y todas las comisiones. No restes dos veces un coste que ya esté incluido en un importe neto. En esta tabla los precios son importes antes de comisiones; estas aparecen por separado. Calcula primero el resultado en dinero y después, si lo necesitas, su porcentaje sobre el desembolso inicial.',n('Simulación: compras por 100 €, pagas 1 € de comisión, vendes por 110 €, cobras 4 € de dividendos y pagas 1 € al vender. ¿Cuál es tu ganancia neta?',12,'€','110 + 4 − 100 − 1 − 1 = 12 €.','Suma los cobros y resta todas las salidas.'),table([['Compra / venta, sin comisiones','100 € / 110 €'],['Dividendo cobrado','4 €'],['Comisión de compra / venta','1 € / 1 €']])) ,
b('Ganancia pendiente y dinero disponible','Si todavía no has vendido, una subida de precio es una ganancia pendiente: cambiará si cambia la cotización. El dividendo ya cobrado sí está en tu cuenta, salvo que lo reinviertas comprando más acciones. Reinvertir no elimina el riesgo de esas nuevas compras. Para distinguir ambos conceptos imagina que la aplicación muestra cuánto valen tus acciones hoy y, en otra línea, el dinero que ya recibiste.',m('Relaciona cada situación del ejemplo con lo que ha ocurrido.',[['La acción sube y la mantienes','Ganancia por precio todavía pendiente'],['La empresa ingresa el dividendo','Dinero ya cobrado'],['Usas ese cobro para comprar más acciones','Reinversión del dividendo']],'Una valoración en pantalla y un ingreso en cuenta no son el mismo movimiento.','Comprueba si hubo cobro o solo cambio de valoración.'))
],ex('¿Qué haces con el dividendo?',['Conservarlo','El dinero queda disponible. Sigue formando parte del resultado de la inversión.'],['Reinvertirlo','Compras más acciones y ese dinero vuelve a quedar expuesto a sus cambios de precio.']));

add(3,'arm','una noticia cambia lo que se espera','NVIDIA y SoftBank anunciaron en febrero de 2022 la cancelación de la compra prevista de Arm por dificultades regulatorias.', ['Distinguir noticia confirmada y expectativa.','Interpretar compradores, vendedores y diferencia de precios.'],[
b('La noticia y la reacción son cosas diferentes','La bolsa reúne compradores y vendedores que negocian según lo que creen que ocurrirá. Una noticia puede cambiar esas expectativas, pero su signo por sí solo no permite predecir el precio: parte de la información quizá ya se esperaba. No reconstruiremos la cotización del anuncio real. Las ofertas de la práctica son inventadas para entender cómo una operación concreta encuentra a la otra parte.',u('Tras una noticia empresarial, ¿qué dos preguntas ayudan a entender una posible reacción?', ['¿Qué esperaban los inversores antes del anuncio?','¿Qué cambia en los resultados futuros que imaginaban?'],['¿La palabra positiva obliga al precio a subir?','¿Todos los inversores deben interpretar igual el anuncio?'],'La comparación útil es entre lo esperado y la nueva información; no hay una reacción obligatoria.','Distingue el hecho publicado de lo que ya estaba descontado.')),
b('Comprar y vender no ofrecen el mismo precio','En un mercado puede haber alguien dispuesto a comprar a un precio y otra persona dispuesta a vender a uno algo mayor. La diferencia entre ambas ofertas se llama diferencial. Comprar inmediatamente suele implicar aceptar la mejor oferta de venta disponible; vender inmediatamente, la de compra. Aquí suponemos que las ofertas tienen cantidad suficiente, no cambian y no hay comisiones para aislar el efecto de esa diferencia.',n('Libro de ofertas simulado: compran a 49 € y venden a 50 €. Compras una acción y la revendes inmediatamente con las ofertas iguales. ¿Cuántos euros pierdes?',1,'€','Pagas 50 € y recuperas 49 €: la diferencia es 1 €.','Usa el precio que exige cada lado de la operación.'),table([['Mejor oferta de compra','49 €'],['Mejor oferta de venta','50 €'],['Comisiones en esta práctica','0 €']])) ,
b('Vender acciones existentes no financia una compra empresarial','Cuando compras a otro inversor una acción que ya existía, normalmente le pagas a ese vendedor. Eso es mercado secundario. Cuando una empresa emite nuevas acciones y las coloca entre inversores, hablamos de mercado primario y puede recibir fondos. El volumen negociado cuenta acciones intercambiadas; no equivale a ingresos que obtiene la compañía. Una jornada muy activa puede reflejar desacuerdo o mucha necesidad de negociar.',q('Se intercambian muchas acciones ya existentes tras el anuncio. ¿Qué conclusión es válida?','Ha aumentado la actividad de negociación, sin que eso implique entrada de dinero en la empresa.','Todo el importe negociado se convierte en financiación para la compañía.','En el mercado secundario el dinero circula entre comprador y vendedor.','Pregunta quién vende las acciones.'))
],ex('La misma noticia, dos expectativas previas',['Se esperaba el acuerdo','La cancelación obliga a revisar un escenario que contaba con la operación.'],['Ya se esperaba la cancelación','El titular puede aportar poca novedad. Todavía importa conocer sus condiciones.']));

add(4,'costco','reinvertir y conservar poder de compra','Costco pagó un dividendo especial de 15 dólares por acción en enero de 2024, según su informe anual.', ['Distinguir crecimiento del capital y aportaciones.','Comparar rentabilidad nominal, compuesta y real.'],[
b('Un pago excepcional no promete el siguiente','Un dividendo especial es un reparto extraordinario; no debemos repetirlo automáticamente en una proyección de cada año. Para explorar el interés compuesto usaremos una rentabilidad imaginada y constante. Componer significa que el rendimiento de un año también participa en el siguiente. Es una hipótesis de cálculo, no una trayectoria que una acción deba seguir. Separaremos además el dinero ganado del dinero nuevo que añades tú.',n('Simulación sin aportaciones: empiezas con 100 € y obtienes un 10 % cada año durante dos años, reinvirtiendo todo. ¿Con cuánto terminas?',121,'€','Primer año: 100 × 1,10 = 110. Segundo: 110 × 1,10 = 121.','El segundo porcentaje se aplica al capital que ya ha crecido.')),
b('Más euros no siempre compran más cosas','La rentabilidad nominal cuenta cuánto crece tu dinero. La real compara ese crecimiento con la subida de los precios de lo que compras. Para medirla exactamente dividimos el factor de crecimiento de la inversión entre el de los precios y restamos uno. Si ambos crecen igual, conservas poder de compra. Restar los dos porcentajes es una aproximación útil cuando son pequeños, pero no es la fórmula exacta.',q('Simulación: tu capital aumenta un 5 % y la misma cesta de compra también un 5 %. ¿Qué ha pasado con tu poder de compra?','Se mantiene, antes de costes e impuestos.','Ha aumentado un 5 % porque tienes más euros.','El capital y la cesta se multiplican por el mismo factor.','Compara cuánto crecen ambos, no solo el saldo.'),table([['Capital inicial / final','100 € / 105 €'],['Cesta inicial / final','100 € / 105 €']])) ,
b('No confundas un ingreso tuyo con una rentabilidad','El saldo puede crecer porque la inversión gana dinero, porque tú aportas más o por ambas razones. Antes de atribuir una subida al rendimiento, reconstruye cuándo entró cada aportación. No puedes aplicar a todo el saldo final una tasa anual como si hubiese estado invertido desde el primer día. Este caso no necesita una fórmula avanzada: basta distinguir el origen del dinero y el tiempo que estuvo trabajando.',m('Clasifica los movimientos de esta cartera simulada.',[['Ingreso mensual desde tu cuenta','Aportación propia'],['Rendimiento reinvertido','Ganancia que permanece invertida'],['Subida del coste de una cesta','Pérdida de poder de compra por euro']],'La aportación no es una ganancia y la inflación no es una comisión cobrada por el bróker.','Identifica de dónde proviene cada cambio.'))
],ex('¿Se repite el dividendo especial?',['No se repite','La simulación de ingresos futuros debe excluirlo si no existe una hipótesis justificada de otro reparto.'],['Se reinvierte el cobrado','El dinero recibido compra más activos. Eso no obliga a la empresa a pagar otro dividendo especial.']));

add(5,'svb','poder esperar también cuenta','La revisión de la Reserva Federal sobre la caída de SVB en marzo de 2023 destacó riesgos de concentración, liquidez y gestión.', ['Separar oscilación del precio y deterioro del negocio.','Relacionar necesidad de dinero y capacidad de asumir pérdidas.'],[
b('La palabra riesgo esconde problemas distintos','Una acción puede bajar por cambios de expectativas, pero también porque la empresa tenga dificultades reales para pagar o mantener su actividad. La volatilidad describe variaciones del precio; no demuestra por sí sola que un negocio sea sano o esté arruinado. En el caso de SVB hubo problemas empresariales concretos. Para analizarlos conviene nombrar el mecanismo de pérdida, en lugar de tratar cualquier caída como una oportunidad.',q('Un banco pierde depósitos y debe conseguir efectivo con urgencia. ¿Qué debe investigarse primero?','Si dispone de recursos líquidos suficientes para atender las salidas.','Solo cuánto ha bajado su acción respecto al máximo.','La necesidad de efectivo es un riesgo del negocio que un gráfico de precios no resuelve.','Relaciona el problema descrito con la capacidad de pagar.')),
b('Recuperar una caída exige otra base','Después de perder dinero, el porcentaje necesario para recuperar el punto inicial se calcula sobre el capital que queda. Por eso una caída y una subida del mismo porcentaje no se compensan. Tampoco hay un plazo garantizado para recuperarse. La tabla es una inversión ficticia: no representa la evolución bursátil de SVB. Sirve para entender por qué el tamaño de una pérdida importa incluso antes de analizar sus causas.',n('Una inversión simulada pasa de 100 € a 60 €. ¿Qué subida porcentual necesita desde 60 € para volver a 100 €? Redondea a dos decimales.',66.67,'%','Faltan 40 €. Sobre los 60 € restantes: 40 ÷ 60 × 100 = 66,67 %.','La base es el dinero que queda, no el inicial.'),table([['Valor inicial','100 €'],['Valor después de la caída','60 €']])) ,
b('Dos personas no pueden esperar lo mismo','La disposición al riesgo es cuánto malestar toleras. La capacidad es cuánto daño económico puedes absorber sin incumplir tus necesidades. Una persona tranquila puede necesitar el dinero muy pronto y tener poca capacidad de esperar. Otra puede disponer de ahorro para emergencias, aunque no soporte ver oscilaciones. Ninguna situación convierte una acción en segura; ayuda a decidir si ese riesgo encaja con el uso previsto del dinero.',u('Una persona necesita pagar una matrícula dentro de dos meses. ¿Qué dos datos importan antes de invertir ese dinero en acciones?', ['Si tiene otra reserva para pagar la matrícula','Qué ocurriría si necesitara vender con pérdidas'],['Si le gusta mucho la marca','Si un conocido asegura que pronto recuperará'],'El compromiso próximo limita la capacidad de soportar pérdidas y de esperar.','Céntrate en las consecuencias de necesitar el dinero.'))
],ex('Una bajada del 20 % en dos situaciones',['Ahorro para un pago próximo','Puede obligar a vender en mal momento para cumplir el pago.'],['Dinero sin uso previsto próximo','Puede permitir esperar, pero no soluciona una quiebra ni hace inevitable la recuperación.']));

add(6,'nvda','enviar una orden con límites claros','NVIDIA dividió cada acción en diez en junio de 2024. Sus cifras por acción se ajustaron para reflejar ese cambio.', ['Elegir órdenes según precio y ejecución.','Revisar cantidad, costes y validez antes de comprar.'],[
b('Primero identifica qué estás comprando','Antes de enviar una orden comprueba la empresa, el mercado, la moneda y la cantidad de acciones. Un cambio en el número de acciones puede hacer que un precio antiguo deje de ser comparable con el actual. En esta práctica no utilizaremos precios históricos de NVIDIA ni negociaremos dinero real: revisaremos una orden ficticia para evitar errores de cantidad y de precio máximo.',m('Relaciona estos controles de una orden simulada con el error que evitan.',[['Comprobar nombre e identificador','Comprar otro instrumento'],['Revisar moneda y conversión','Confundir euros con dólares'],['Revisar cantidad de acciones','Comprar más unidades de las previstas']],'Cada control resuelve un riesgo operativo diferente.','Relaciona el campo con la equivocación concreta.')),
b('Una orden limitada pone techo al precio de compra','Una orden de compra limitada indica el precio máximo que aceptas por acción. Puede ejecutarse a ese precio o a uno mejor, pero puede quedarse sin ejecutar si no aparece una oferta compatible. La orden a mercado prioriza ejecutarse con las ofertas disponibles y no fija ese techo. En ambos casos pueden existir comisiones. Aquí todas las cifras están expresadas en euros para no mezclar la cuenta con una conversión de moneda.',q('Simulación: quieres comprar hasta 3 acciones sin pagar más de 20 € por cada una. La mejor oferta de venta es 21 €. ¿Qué hace una compra limitada a 20 €?','Espera una oferta compatible y puede no ejecutarse.','Compra inmediatamente a 21 € porque solo supera el límite en un euro.','El límite no se ignora por ser pequeña la diferencia.','Recuerda qué condición debe cumplir el vendedor.'),table([['Cantidad máxima','3 acciones'],['Precio límite de compra','20 €'],['Mejor venta disponible','21 €']])) ,
b('Una ejecución parcial sigue dejando una orden pendiente','A veces solo hay acciones suficientes para cubrir parte de tu solicitud. Entonces debes distinguir lo comprado de lo que sigue pendiente. La vigencia establece hasta cuándo puede continuar esa parte sin ejecutar. Antes de repetir una orden, revisa su estado para no duplicar la compra. Una orden stop, cuando se activa, tampoco garantiza siempre el precio final: depende de si se transforma en orden a mercado o limitada.',o('Ordena esta revisión después de recibir una ejecución parcial.', ['Consultar cuántas acciones se han comprado','Revisar cantidad pendiente y vigencia','Decidir si mantener o cancelar lo pendiente'],'Primero averigua qué ocurrió; después decide sobre lo que aún puede ejecutarse.','No envíes otra compra antes de conocer el estado de la primera.'))
],ex('¿Qué prioridad eliges en la simulación?',['Precio máximo','Una orden limitada protege ese límite, a cambio de poder no comprar.'],['Ejecución inmediata','Una orden a mercado utiliza ofertas disponibles y puede acabar a varios precios.']));

add(7,'berkshire','varios negocios y riesgos compartidos','El informe de Berkshire Hathaway de 2023 describe negocios como seguros y el ferrocarril BNSF, además de inversiones financieras.', ['Calcular pesos de cartera.','Detectar concentraciones que no se ven contando empresas.'],[
b('Cuatro nombres no siempre son cuatro riesgos','La diversificación reparte la exposición entre inversiones cuyo comportamiento no depende exactamente de lo mismo. Contar empresas no basta: varias pueden vender al mismo cliente, necesitar el mismo proveedor o sufrir cuando cae un sector. Berkshire permite pensar en negocios diferentes dentro de un grupo, pero comprar una sola sociedad sigue concentrando riesgos propios de esa sociedad. La cartera de la práctica será ficticia y estará separada de sus posiciones reales.',u('Una cartera simulada contiene cuatro fabricantes que venden casi todo a un mismo constructor. ¿Qué dos cosas revisarías?', ['La proporción de ventas ligada a ese cliente común','Qué ocurriría si el constructor dejara de comprar'],['Solo que los cuatro nombres sean distintos','Solo el número de acciones de cada empresa'],'La dependencia común puede hacer que las cuatro posiciones sufran juntas.','Busca el factor que comparten los negocios.')),
b('Los pesos se calculan por valor, no por unidades','El peso de una inversión es su valor dividido entre el valor total de la cartera. Tener diez acciones de cada empresa no implica repartir el dinero por igual, porque cada acción puede valer una cantidad diferente. Para conocer la concentración agrupa después los pesos que dependen del mismo sector o factor. Usa valores de la misma fecha y moneda; aquí ya los hemos expresado todos en euros.',n('Cartera simulada: empresa A vale 300 €, B vale 100 € y C vale 100 €. A y B dependen del mismo sector. ¿Qué porcentaje está en ese sector?',80,'%','A y B suman 400 € sobre 500 € totales: 80 %.','Suma primero los valores expuestos al mismo factor.'),table([['Empresa A, sector X','300 €'],['Empresa B, sector X','100 €'],['Empresa C, sector Y','100 €']])) ,
b('Diversificar reduce algunos riesgos, no todos','Añadir negocios diferentes puede disminuir el daño de un problema particular, como perder un cliente importante. No elimina automáticamente riesgos amplios que afecten a muchas empresas a la vez, como una crisis económica. Un fondo también puede concentrarse en un solo sector aunque contenga muchas acciones. Por eso hay que mirar qué posee realmente y cómo encaja con lo que ya tienes, no limitarse a añadir otro nombre al listado.',q('Ya tienes tres tecnológicas. Añades un fondo que invierte sobre todo en esas mismas empresas. ¿Qué conclusión es más prudente?','Puede aumentar la exposición repetida en lugar de diversificar mucho.','Un fondo siempre elimina la concentración previa.','El vehículo cambia, pero las empresas de dentro pueden coincidir.','Mira las inversiones del fondo, no solo su etiqueta.'))
],ex('Dos formas de añadir una posición',['Mismo factor de riesgo','Otra empresa del mismo nicho puede reforzar la dependencia existente.'],['Otra fuente de ingresos','Un negocio diferente puede repartir riesgos específicos, aunque conserve exposición al mercado.']));

add(8,'costco','leer el período antes del titular','El ejercicio 2024 de Costco tuvo 52 semanas; el anterior, 53. El informe anual explica esta diferencia.', ['Comprobar fuente, unidad y período de un dato.','Distinguir hecho publicado, ajuste y estimación.'],[
b('Dos cifras pueden ser correctas y no ser comparables','Un informe anual describe un período concreto, que no tiene por qué coincidir con el año natural. Antes de comparar crecimiento, revisa fechas, moneda, unidad y duración. Una semana adicional puede elevar las ventas del período más largo sin que haya mejorado el ritmo del negocio. No hay que descartar los informes: hay que leer sus notas y explicar qué comparación se está haciendo.',q('Un titular compara dos ejercicios de distinta duración y atribuye toda la diferencia a más demanda. ¿Qué falta?','Separar el efecto del calendario antes de interpretar el cambio.','Sustituir los datos oficiales por la opinión con más seguidores.','La duración del período afecta a cuánto se puede vender dentro de él.','Comprueba si ambos intervalos ofrecen el mismo tiempo para vender.')),
b('Haz una comparación pequeña y transparente','Para aislar el calendario en esta simulación supondremos ventas iguales cada semana. Dividir las ventas entre semanas permite comparar un ritmo semanal, pero en un negocio real habría estacionalidad y cambios de precios. Por eso el cálculo es una herramienta, no una corrección universal. Deja escrita la hipótesis que utilizas y no presentes el resultado del ajuste como si fuera una cifra que publicó la compañía.',n('Datos simulados: período A vende 530 unidades en 53 semanas y B vende 520 en 52. ¿Cuántas unidades vende por semana B?',10,'unidades por semana','520 ÷ 52 = 10. A también promedia 10; la diferencia total proviene aquí solo de la duración.','Divide las ventas del período B entre sus semanas.'),table([['Período A','530 unidades / 53 semanas'],['Período B','520 unidades / 52 semanas']])) ,
b('Guarda la procedencia junto al dato','Una ficha útil distingue lo publicado, lo calculado por ti y lo que crees que podría pasar. Anota el documento y el apartado para poder volver a comprobarlo. Una presentación de la compañía es una fuente directa, aunque también tenga una intención comercial; una opinión externa puede aportar ideas, pero no sustituye la comprobación del hecho original. Las estimaciones deben conservar su fecha porque cambian al aparecer información nueva.',m('Clasifica estas notas de una investigación simulada.',[['El informe dice que el ejercicio tiene 52 semanas','Hecho publicado'],['Divido las ventas entre semanas','Cálculo propio'],['Creo que las ventas crecerán el próximo año','Estimación']],'La etiqueta muestra qué se sabe, qué se calcula y qué todavía se supone.','Pregunta de dónde sale cada frase.'))
],ex('¿Qué guardas en tu ficha?',['Solo el número','Después puede ser imposible saber qué moneda, período o definición utilizaste.'],['Número con contexto','Documento, fecha, unidad y definición permiten repetir la comprobación.']));

add(9,'adobe','quién utiliza, quién paga y por qué vuelve','Adobe explicó en su informe de 2024 que una parte de sus ingresos procede de suscripciones a servicios como Creative Cloud.', ['Describir el cliente y el servicio que paga.','Distinguir cobros recurrentes y ventas puntuales.'],[
b('Un producto conocido no explica todo el negocio','Para describir un modelo de negocio empieza por una necesidad concreta: qué problema resuelve y para quién. Después identifica quién paga, cómo accede al producto y qué necesita la empresa para prestarlo. Usuario y pagador pueden ser personas diferentes, como un trabajador y su empresa. No hace falta empezar por cifras de valoración: una descripción clara del intercambio es la base para entender los ingresos posteriores.',m('En una empresa imaginada que contrata programas de diseño, relaciona cada papel.',[['Diseñadora que usa el programa','Usuaria'],['Empresa que paga la licencia','Cliente pagador'],['Proveedor que mantiene el servicio','Empresa que presta la solución']],'Usar, pagar y prestar el servicio son funciones diferentes aunque a veces coincidan.','Identifica la función de cada participante.')),
b('Recurrente significa que debe renovarse','Una suscripción genera pagos mientras el cliente mantenga el servicio; no significa ingresos eternos ni sin esfuerzo. La empresa debe conservar su utilidad, atender al cliente y asumir los costes de prestarlo. Una venta puntual se cobra por una operación concreta y necesita repetirse o encontrar otro comprador para generar un ingreso nuevo. El ejemplo compara contratos simulados, no precios ni condiciones comerciales reales de Adobe.',q('Simulación: A vende una licencia definitiva por 120 €; B cobra 10 € al mes mientras el cliente continúe. ¿Qué necesita B para ingresar durante el segundo año?','Que el cliente siga pagando y el servicio continúe prestándose.','Nada: la primera suscripción asegura todos los pagos futuros.','La recurrencia depende de conservar el contrato, no solo de haber conseguido una primera venta.','Piensa qué puede hacer el cliente al terminar el período.'),table([['Oferta A','120 € por licencia definitiva'],['Oferta B','10 € al mes mientras siga activa']])) ,
b('Relaciona el canal con el ingreso','Un canal es el medio por el que el producto llega al cliente: venta directa, distribuidores o una plataforma, por ejemplo. Puede facilitar acceso a clientes y a cambio exigir costes o comisiones. Para entender un negocio debes seguir el recorrido desde la necesidad hasta el pago, sin confundir visitas gratuitas con clientes de pago. Una herramienta muy utilizada puede monetizar solo una parte de sus usuarios y seguir necesitando recursos para atenderlos.',o('Ordena una investigación básica de este negocio de software.', ['Identificar qué tarea resuelve y para quién','Averiguar quién paga y bajo qué contrato','Revisar cómo se entrega el servicio y qué recursos necesita'],'Primero define el intercambio; después examina cómo se hace posible.','No empieces por contar usuarios sin saber qué papel tienen.'))
],ex('¿Qué significa crecer en usuarios?',['Usuarios gratuitos','Muestran uso, pero no prueban por sí solos que aumenten los cobros.'],['Contratos de pago activos','Se relacionan con ingresos, aunque hay que revisar importe, permanencia y coste de atenderlos.']));

add(10,'unilever','crecer vendiendo más o cobrando más','Unilever desglosó su crecimiento subyacente de 2024 entre volumen y precio, y separó los efectos de moneda y cambios en el grupo.', ['Descomponer ventas entre precio y cantidad.','Separar crecimiento propio, adquisiciones y divisas.'],[
b('El total esconde distintos motores','Las ventas de un producto dependen de cuántas unidades se venden y del precio de cada una. El total también puede cambiar porque se incorporen negocios comprados o porque al convertir otra moneda obtengamos un importe distinto. El crecimiento orgánico intenta aislar la actividad comparable, pero hay que leer cómo lo define cada compañía. En la práctica utilizaremos un solo producto ficticio, sin divisas ni adquisiciones, para ver el efecto combinado.',n('Producto simulado: pasa de 100 unidades a 10 € a 110 unidades a 12 €. ¿Cuánto aumentan las ventas en euros?',320,'€','Antes: 1.000 €. Después: 1.320 €. Aumento: 320 €.','Calcula precio por cantidad en ambos períodos y compara.')),
b('Los porcentajes de precio y cantidad se combinan','Si aumenta tanto el precio como la cantidad, las nuevas unidades también se venden al nuevo precio. Por eso sumar dos porcentajes de crecimiento puede ser solo una aproximación. Además, vender una mezcla de productos más caros puede elevar el precio medio sin haber subido cada tarifa individual. Esa mezcla se suele llamar mix. Para explicar un cambio conviene saber si se han vendido más unidades, otras unidades o las mismas a otro precio.',q('Una empresa simulada mantiene el precio de cada producto, pero vende más del modelo caro y menos del barato. ¿Qué puede ocurrir?','Sube el precio medio por cambiar la mezcla de ventas.','Todo aumento del precio medio demuestra una subida de cada tarifa.','El promedio también depende del peso de cada producto.','Distingue el precio de una referencia del promedio de todas.'),table([['Producto básico','10 € por unidad'],['Producto superior','20 € por unidad'],['Cambio del período','Más peso del producto superior']])) ,
b('Atribuye cada cambio a su causa','Comprar otra empresa añade sus ventas al grupo, pero no demuestra que el negocio anterior venda más. Del mismo modo, una moneda extranjera más fuerte puede elevar ventas convertidas sin aumentar unidades. Separar los motores evita atribuir a demanda lo que se explica por otra causa. No hay que llamar malo a todo efecto externo: simplemente conviene saber qué cambió y si podría repetirse el año siguiente.',m('Relaciona tres cambios simulados con el motor correspondiente.',[['Se incorpora una marca comprada','Cambio de perímetro'],['El mismo cobro extranjero vale más euros','Efecto de conversión de moneda'],['Las tiendas existentes venden más unidades','Crecimiento del volumen comparable']],'Cada motor explica una parte diferente del crecimiento publicado.','Sigue el origen del incremento antes de juzgarlo.'))
],ex('Dos aumentos iguales del total',['Más unidades comparables','Aporta una señal de mayor actividad en el negocio existente.'],['Una empresa adquirida','Añade ventas al grupo, pero exige estudiar también lo pagado por incorporarlas.']));

add(11,'cat','vender menos y conservar margen','Caterpillar publicó menores ventas en 2024, pero un margen operativo superior al de 2023.', ['Distinguir costes fijos, variables y margen.','Calcular el punto de equilibrio sin confundirlo con ventas.'],[
b('No todo coste baja cuando vendes menos','Un coste variable cambia con la cantidad producida o vendida; un coste fijo permanece dentro del intervalo que estamos estudiando. El alquiler de una instalación no desaparece porque se venda una máquina menos. El margen de contribución es el precio menos el coste variable por unidad: sirve para cubrir costes fijos y, después, generar beneficio. Este modelo simplifica una fábrica imaginada y no reproduce la estructura real de Caterpillar.',m('Para la fábrica simulada, clasifica estos importes.',[['Material utilizado por cada máquina','Coste variable'],['Alquiler mensual pactado','Coste fijo en este intervalo'],['Precio menos material por máquina','Contribución por unidad']],'La clasificación depende de si el coste cambia al fabricar una unidad adicional.','Mantén el horizonte mensual y la misma capacidad de fábrica.')),
b('El equilibrio se alcanza cubriendo los costes fijos','Si cada venta deja una contribución, puedes calcular cuántas unidades necesitas para cubrir los costes fijos. Divide esos costes entre la contribución por unidad. El punto de equilibrio no dice que el negocio genere caja suficiente para toda inversión futura; solo señala cuándo el beneficio de este modelo deja de ser negativo. Mantendremos constantes el precio, el coste variable y la capacidad durante toda la práctica.',n('Fábrica simulada: precio de 50 € por unidad, coste variable de 30 € y costes fijos de 200 €. ¿Cuántas unidades debe vender para cubrir exactamente estos costes?',10,'unidades','Cada unidad aporta 20 €. Para cubrir 200 € hacen falta 200 ÷ 20 = 10.','Calcula primero cuánto aporta una unidad.'),table([['Precio unitario','50 €'],['Coste variable unitario','30 €'],['Costes fijos','200 €']])) ,
b('Porcentaje y cantidad pueden contar historias distintas','El margen operativo compara el beneficio de la actividad con las ventas. Puede aumentar aunque el beneficio en euros disminuya, si las ventas caen más. También puede mejorar por precio, mezcla de productos o control de gastos. Para interpretar el cambio debes mirar las dos cantidades, no solo el porcentaje. El apalancamiento operativo describe cómo los costes fijos amplifican el efecto de una variación de ventas sobre el beneficio.',q('Simulación: las ventas pasan de 100 a 80 y el beneficio operativo de 10 a 12. ¿Qué conclusión encaja?','El margen mejora y también aumenta el beneficio en euros.','El margen empeora necesariamente porque bajan las ventas.','El margen pasa del 10 % al 15 % y el beneficio aumenta en 2.','Divide beneficio entre ventas en cada período.'))
],ex('Con el mismo alquiler de fábrica',['Pocas unidades','Cada unidad debe cubrir una parte mayor del coste fijo total.'],['Más unidades, sin ampliar capacidad','El coste fijo se reparte entre más unidades; eso puede mejorar el margen.']));

add(12,'costco','una ventaja necesita pruebas','Costco informó de una tasa de renovación de socios del 90 % en su carta del informe anual de 2024.', ['Relacionar fidelidad con evidencia de ventaja competitiva.','Distinguir una señal útil de una prueba suficiente.'],[
b('Renovar aporta información, pero no responde a todo','Una ventaja competitiva permite ofrecer algo que los rivales tienen dificultad para igualar de forma duradera. Puede proceder de costes, marca, escala o comodidad. La renovación de clientes aporta una señal de utilidad, pero no demuestra por sí sola altos beneficios ni explica por qué vuelven. Hace falta revisar el precio que pagan, el coste de atenderlos y las alternativas disponibles. No confundas popularidad con una ventaja ya demostrada.',q('En una empresa ficticia renuevan muchos clientes, pero solo tras un descuento que elimina casi todo el margen. ¿Qué falta para valorar la ventaja?','Comprobar si la fidelidad puede mantenerse con una economía rentable.','Dar por probada la ventaja porque la renovación es alta.','La permanencia del cliente no basta si se compra a un coste que destruye el resultado.','Relaciona retención y coste de conseguirla.')),
b('Una comparación debe mantener condiciones parecidas','Para estudiar fidelidad, compara grupos con contratos y períodos semejantes. Si un grupo recibe regalos y otro no, la diferencia de renovación no se puede atribuir solo al producto. En la tabla todos terminan un contrato anual bajo las mismas condiciones, lo que simplifica el cálculo. La retención se obtiene dividiendo quienes siguen entre quienes podían renovar, no entre todos los usuarios que llegaron durante el año.',n('Grupo simulado: 80 clientes podían renovar y 68 lo hacen. ¿Qué porcentaje de ese grupo renueva?',85,'%','68 ÷ 80 × 100 = 85 %. No se incluyen clientes nuevos que aún no tenían que renovar.','Usa como base solo los contratos que podían renovarse.'),table([['Clientes que podían renovar','80'],['Clientes que renovaron','68'],['Condiciones de comparación','Mismo contrato y período']])) ,
b('Busca el mecanismo que sostiene la ventaja','Decir que una empresa tiene marca es el comienzo de una hipótesis, no su demostración. Hay que explicar si permite cobrar más, vender con menos publicidad o conservar clientes. Los costes de cambio son el tiempo, dinero o esfuerzo que exige pasar a otro proveedor. Pueden ayudar a retener, pero una alternativa mucho mejor puede superarlos. Una buena investigación busca datos que apoyen el mecanismo y datos que podrían refutarlo.',u('Una tesis simulada afirma que cambiar de programa resulta costoso. ¿Qué dos evidencias serían pertinentes?', ['Tiempo necesario para trasladar los datos','Formación requerida para usar la alternativa'],['El color del logotipo','El precio máximo histórico de la acción'],'Migración y aprendizaje son costes de cambio concretos.','Busca esfuerzos que afronta el cliente, no características bursátiles.'))
],ex('Dos motivos para seguir pagando',['Utilidad persistente','El servicio sigue resolviendo una necesidad mejor que las alternativas.'],['Descuento temporal','El cliente puede marcharse cuando desaparezca el incentivo; conviene comprobarlo.']));

add(13,'msft','del ingreso al beneficio','Microsoft presentó en su informe del ejercicio 2024 ingresos anuales superiores a 245.000 millones de dólares.', ['Leer los escalones de la cuenta de resultados.','No confundir beneficio, EBITDA y efectivo.'],[
b('Las ventas son el comienzo de la cuenta','La cuenta de resultados resume ingresos y gastos de un período. Para llegar al beneficio hay que restar lo que cuesta prestar el servicio, los gastos de funcionamiento y, después, partidas como intereses e impuestos. No todo se paga o cobra en ese mismo momento. La amortización reparte el coste de un activo entre los períodos que lo utilizan; por eso aparece como gasto aunque la compra se haya pagado antes.',o('Ordena estos grandes escalones de una cuenta de resultados simplificada.', ['Ingresos menos costes y gastos operativos','Resultado antes de impuestos tras intereses','Resultado neto después de impuestos'],'Cada escalón incorpora gastos que el anterior todavía no había restado.','Empieza por el negocio y termina después de intereses e impuestos.')),
b('Reconstruye el resultado sin saltarte un gasto','El beneficio operativo es lo que queda tras los gastos de la actividad, incluida la amortización cuando corresponde. El EBITDA los presenta antes de intereses, impuestos y amortizaciones; no es la cantidad que hay en el banco. En este ejercicio los gastos de la tabla ya incluyen la amortización, así que no debes restarla otra vez. Usamos una compañía simulada con importes reducidos para seguir cada escalón sin perder el significado.',n('Cuenta simulada: ingresos 200 €, gastos operativos totales 150 €, intereses 10 € e impuestos 8 €. ¿Cuál es el beneficio neto?',32,'€','200 − 150 − 10 − 8 = 32 €. La amortización ya está incluida en los gastos operativos.','Resta cada concepto una sola vez.'),table([['Ingresos','200 €'],['Gastos operativos, incluida amortización','150 €'],['Intereses / impuestos','10 € / 8 €']])) ,
b('Los ajustes necesitan una explicación','Una empresa puede presentar un beneficio ajustado excluyendo determinados gastos. Ese dato puede ayudar a estudiar lo recurrente, pero no reemplaza automáticamente el resultado contable. Revisa qué se excluye, por qué y cuántos años se repite. Un gasto descrito como excepcional cada ejercicio merece atención. La conciliación es el puente que permite pasar de una medida a otra y comprobar que las diferencias no se han escondido.',q('Una empresa simulada excluye de su resultado ajustado un gasto que se repite todos los años. ¿Qué harías?','Investigar si ese coste forma parte habitual de operar antes de aceptarlo como excepcional.','Eliminarlo del análisis porque la etiqueta ajustado lo autoriza.','El nombre de la medida no decide si un coste es recurrente.','Mira el historial del gasto, no solo su etiqueta.'))
],ex('Dos formas de presentar el resultado',['Resultado contable','Incluye los ingresos y gastos reconocidos conforme al marco contable.'],['Resultado ajustado','Selecciona exclusiones que deben explicarse y reconciliarse con el contable.']));

add(14,'inditex','lo que hay y lo que se debe','Inditex publica un balance a cierre de enero; su ejercicio 2024 terminó el 31 de enero de 2025.', ['Separar activos, obligaciones y patrimonio.','Evaluar liquidez sin confundir existencias con caja.'],[
b('El balance es una foto con fecha','El balance muestra recursos y obligaciones en un momento concreto. Los activos son recursos reconocidos por la empresa, como caja, existencias o equipos. Los pasivos son obligaciones, como facturas pendientes o préstamos. El patrimonio es la diferencia contable entre ambos. No equivale necesariamente al precio de mercado de todas las acciones. Un negocio puede tener muchos activos y poca caja disponible si sus recursos están inmovilizados en mercancías o edificios.',m('Relaciona estas partidas de una tienda simulada.',[['Dinero en la cuenta bancaria','Activo líquido'],['Factura pendiente de un proveedor','Pasivo'],['Activos menos pasivos','Patrimonio contable']],'La diferencia entre recursos y obligaciones corresponde al patrimonio, no a un cobro inmediato.','Distingue lo disponible, lo debido y la diferencia.')),
b('La igualdad ayuda a detectar errores','La relación básica es activos igual a pasivos más patrimonio. Si conoces dos de esas magnitudes, puedes obtener la tercera. Sin embargo, cuadrar el balance no demuestra que todos los activos puedan venderse por su valor contable ni que los cobros lleguen a tiempo. En esta tabla los importes pertenecen a una tienda ficticia y están medidos en la misma fecha, sin mezclarlos con ventas de todo el año.',n('Balance simulado: caja 20 €, existencias 30 € y equipos 50 €. Debe 40 € en total. ¿Cuánto patrimonio contable tiene?',60,'€','Activos: 20 + 30 + 50 = 100. Patrimonio: 100 − 40 = 60 €.','Suma los recursos antes de restar las obligaciones.'),table([['Caja / existencias / equipos','20 € / 30 € / 50 €'],['Obligaciones totales','40 €']])) ,
b('Pagar mañana exige dinero a tiempo','La liquidez es la capacidad de atender pagos cuando vencen. Tener existencias puede ser útil para vender, pero primero hay que convertirlas en ventas y cobrar. Un equipo puede valer mucho y ser difícil de vender rápidamente sin perjudicar la actividad. Para juzgar liquidez compara vencimientos con caja y cobros razonablemente disponibles; no sumes todos los activos como si fueran billetes en la cuenta.',q('Una tienda simulada tiene 5 € de caja, mercancía por 100 € y una factura de 20 € que vence mañana. ¿Qué falta comprobar?','Si puede obtener a tiempo los 15 € que le faltan para pagar.','Nada: tener existencias superiores a la factura basta para pagar mañana.','La mercancía no liquida automáticamente una factura. Importa el calendario de conversión a efectivo.','Compara el vencimiento con recursos realmente disponibles.'))
],ex('El mismo valor contable, distinta disponibilidad',['Dinero en cuenta','Puede servir para pagar si no está restringido.'],['Mercancía en almacén','Necesita venderse y cobrarse; puede exigir descuentos o tiempo.']));

add(15,'ti','la caja que queda tras invertir','Texas Instruments publicó en 2024 flujo operativo de 6.318 millones de dólares e inversiones de 4.820 millones.', ['Separar flujos operativos, de inversión y financiación.','Calcular flujo libre con una definición explícita.'],[
b('Los movimientos de caja tienen distintas causas','El estado de flujos explica cómo cambia el efectivo. Las operaciones recogen cobros y pagos vinculados a la actividad; la inversión incluye compras de equipos; la financiación incluye préstamos o pagos a propietarios. Que entre dinero no significa siempre que se haya ganado: pedir prestado aumenta la caja y también una obligación. La definición de flujo libre que usaremos resta la inversión en equipos al flujo operativo, como en la conciliación de Texas Instruments.',q('Una empresa simulada recibe 50 € de un préstamo. ¿Cómo lo interpretarías?','Es una entrada de financiación, no una venta ni un beneficio operativo.','Es flujo operativo porque aumenta la caja disponible.','El origen del dinero determina su clasificación.','Comprueba por qué ha entrado el dinero.')),
b('La inversión consume parte de lo generado','El flujo operativo muestra efectivo generado por la actividad, pero la empresa puede necesitar equipos para mantenerla o ampliarla. Restar esos desembolsos permite ver cuánto queda bajo esta definición de flujo libre. No hay que volver a restar una amortización contable: no es un pago adicional del período. Tampoco conviene tratar toda inversión como opcional, porque parte puede ser necesaria para seguir funcionando.',n('Simulación: flujo operativo de 80 € y compra de equipos de 55 €. Según la definición explicada, ¿cuánto flujo libre queda?',25,'€','80 − 55 = 25 €.','Resta la inversión pagada, no la amortización contable.'),table([['Flujo operativo','80 €'],['Equipos pagados','55 €'],['Definición empleada','Operativo menos inversión en equipos']])) ,
b('Conciliar evita confundir financiación y generación','La caja final debe poder explicarse a partir de la inicial y de los movimientos del período, incluyendo otros efectos identificados cuando existan. Un dividendo puede financiarse con caja antigua o deuda aunque el flujo libre del año sea menor. Por eso mirar solo cuánto se reparte no demuestra cuánto genera el negocio. En la siguiente revisión no hay cambios de moneda ni partidas omitidas: cada movimiento tiene una causa definida.',m('Clasifica los movimientos simulados.',[['Cobrar facturas de clientes','Operaciones'],['Comprar una máquina','Inversión'],['Devolver un préstamo','Financiación']],'La compra de un activo y la devolución de deuda reducen caja por motivos distintos.','Sigue la causa del pago, no solo su signo.'))
],ex('Mismo flujo operativo, diferente inversión',['Reponer equipos necesarios','El pago reduce el efectivo que queda para otros usos.'],['Posponer equipos temporalmente','La caja puede parecer mejor hoy, pero debe estudiarse el efecto sobre la actividad futura.']));

add(16,'airbnb','cobrar antes no significa ganar antes','Airbnb explica en su informe de 2024 que reconoce el ingreso de las reservas al comenzar la estancia.', ['Distinguir cobro, ingreso y obligación pendiente.','Interpretar el efecto del calendario sobre la caja.'],[
b('El calendario separa dinero y servicio','Un cliente puede pagar antes de recibir un servicio. Ese cobro mejora la caja, pero la empresa todavía tiene una obligación pendiente. El ingreso se reconoce cuando corresponde a la prestación, según sus condiciones contables. En una plataforma también puede haber dinero cobrado por cuenta de terceros que no pertenece a sus ingresos. Separar estos conceptos evita tratar todo saldo recibido como beneficio disponible para repartir.',m('En un alojamiento simulado, relaciona cada momento.',[['El huésped paga antes del viaje','Entra efectivo'],['Todavía falta prestar la estancia','Existe una obligación pendiente'],['Se cumple el servicio que genera la comisión','Se reconoce el ingreso correspondiente']],'El movimiento bancario y el cumplimiento del servicio no tienen por qué coincidir.','Separa cuándo se paga de cuándo se presta.')),
b('Una venta a crédito puede dar beneficio sin caja','La diferencia también funciona al revés: una empresa puede reconocer una venta y cobrarla más tarde. Mientras tanto, ese importe es una cuenta a cobrar. Si debe pagar salarios o proveedores antes, necesitará financiación temporal. Para aislarlo, el ejercicio utiliza una empresa ficticia que no es la plataforma real y supone que los costes indicados se pagan de inmediato, sin existencias ni impuestos.',n('Servicio simulado: reconoce ventas de 100 €, cobra solo 60 € este mes y paga costes de 70 €. ¿Cuánto efectivo le falta este mes para cubrir esos pagos?',10,'€','Cobra 60 y paga 70: faltan 10 €. El beneficio contable de 30 no resuelve ese desfase.','Compara cobros con pagos, no ingresos con gastos.'),table([['Ventas reconocidas','100 €'],['Cobros del mes','60 €'],['Costes pagados','70 €']])) ,
b('El circulante conecta la actividad con sus cobros','El capital circulante operativo reúne recursos atados al ciclo del negocio, como facturas por cobrar y existencias, descontando financiación de proveedores y anticipos cuando proceda. Si los clientes tardan más en pagar, puede consumir caja aunque las ventas crezcan. Un cobro anticipado puede aportar financiación temporal, pero viene acompañado de compromisos. Antes de celebrar una mejora de caja, pregunta qué pagos o servicios faltan por cumplir y cuándo vencen.',q('Una empresa simulada mejora la caja porque retrasa el pago a proveedores, sin cambiar ventas. ¿Qué conclusión es prudente?','Ha cambiado el calendario de pagos; no necesariamente la rentabilidad del negocio.','Ha creado beneficio adicional por no pagar todavía.','Posponer un pago conserva caja temporalmente, pero no elimina la obligación.','Distingue ahorro de coste y retraso de pago.'))
],ex('Dos calendarios para una misma venta',['Cobro antes de prestar','Aporta dinero temporalmente, mientras sigue pendiente el servicio.'],['Cobro después de prestar','La venta puede figurar en resultados antes de que llegue el efectivo.']));

add(17,'cat','el beneficio necesita un denominador','Caterpillar presenta por separado las ventas y el margen operativo en sus resultados de 2024.', ['Relacionar beneficio con capital empleado.','No atribuir un ROE mayor automáticamente a mejor actividad.'],[
b('Ganar más no siempre significa aprovechar mejor los recursos','Para evaluar un rendimiento hay que comparar el beneficio con los recursos utilizados para obtenerlo. El ROE relaciona beneficio neto y patrimonio de los accionistas; el ROIC compara beneficio operativo después de impuestos con capital invertido en la actividad. Sus numeradores no son intercambiables. En esta práctica usamos capital medio del período y excluimos cambios contables complicados para centrarnos en qué recursos exige cada resultado.',q('Dos fábricas simuladas ganan 10 € operativos después de impuestos. A usa 100 € de capital y B usa 200 €. ¿Cuál lo aprovecha mejor según ROIC?','A, porque consigue el mismo beneficio con menos capital.','Son iguales porque ganan exactamente lo mismo.','A obtiene 10 % y B 5 % con la misma definición.','No olvides los recursos necesarios para ganar.')),
b('Calcula el rendimiento con magnitudes coherentes','El capital invertido financia recursos de la actividad. Para medir su rendimiento, utiliza un beneficio de la actividad después de impuestos y antes de costes de financiación, coherente con ese capital. En la tabla ambos importes ya están preparados con esa definición. No sustituiremos el capital por las ventas ni el beneficio por la caja, porque cada cociente responde a una pregunta distinta sobre el negocio.',n('Fábrica simulada: beneficio operativo después de impuestos de 18 € y capital invertido medio de 120 €. ¿Cuál es su ROIC?',15,'%','18 ÷ 120 × 100 = 15 %.','Divide el beneficio definido entre el capital que lo genera.'),table([['Beneficio operativo después de impuestos','18 €'],['Capital invertido medio','120 €']])) ,
b('La deuda puede alterar el rendimiento del accionista','Si parte de los recursos se financia con deuda, el patrimonio de los accionistas puede ser menor. Eso puede elevar el ROE sin mejorar el funcionamiento de las máquinas ni la demanda. También aumenta obligaciones y riesgo. Para entender el cambio separa margen, uso de activos y financiación. Un ROE alto merece investigar de dónde procede, especialmente si el patrimonio es muy pequeño o hay pérdidas anteriores que lo han reducido.',u('Sube el ROE de una empresa simulada. ¿Qué dos comprobaciones ayudan a entender por qué?', ['Si ha disminuido el patrimonio por más deuda o repartos','Si ha mejorado el beneficio del negocio'],['Si ha cambiado el color de su marca','Si el precio por acción es un número pequeño'],'El cociente cambia por el beneficio o por el patrimonio; después hay que estudiar las causas.','Mira numerador y denominador.'))
],ex('Dos maneras de elevar un cociente',['Mejorar el beneficio con el mismo capital','Puede reflejar una mejora económica que debe comprobarse.'],['Reducir patrimonio mediante financiación','Puede elevar el ROE sin elevar el rendimiento operativo y con más riesgo.']));

add(18,'msft','decidir qué hacer con el dinero','Microsoft informó de recompras financiadas con efectivo dentro de sus programas de adquisición de acciones en 2024.', ['Comparar reinversión, deuda y devolución al accionista.','Evaluar una recompra según precio y necesidades de caja.'],[
b('Cada euro utilizado deja de estar disponible para otro fin','La asignación de capital consiste en decidir entre reinvertir, comprar negocios, reducir deuda, conservar caja o devolver dinero a accionistas. No existe una opción siempre superior. Depende del rendimiento razonable de los proyectos, de las obligaciones y del precio de las alternativas. Una recompra adquiere acciones propias; un dividendo entrega dinero a los propietarios. Ninguno demuestra por sí solo que la dirección esté usando bien los recursos.',m('Relaciona el uso de caja con su efecto inmediato en una empresa simulada.',[['Devolver un préstamo','Reduce una obligación financiera'],['Comprar maquinaria','Añade recursos para la actividad'],['Pagar dividendo','Entrega efectivo a los accionistas']],'Cada uso cambia recursos y compromisos de distinta manera.','Piensa adónde va el dinero, antes de valorar si conviene.')),
b('Una recompra depende del precio que se paga','Con el mismo presupuesto se retiran más acciones cuando el precio es menor. Si se cancelan, el beneficio futuro se reparte entre menos acciones, suponiendo que lo demás no cambie. Pero gastar caja también puede reducir intereses cobrados o exigir deuda: esa condición debe revisarse. El ejercicio aísla solo el número de acciones, sin atribuir ninguna de estas cifras a Microsoft ni afirmar que su precio real fuese adecuado.',n('Simulación: existen 100 acciones. La empresa dedica 200 € a recomprarlas a 20 € cada una y las cancela. ¿Cuántas acciones quedan?',90,'acciones','Recompra 200 ÷ 20 = 10; quedan 100 − 10 = 90.','Primero calcula cuántas puede comprar con el presupuesto.'),table([['Acciones iniciales','100'],['Presupuesto / precio por acción','200 € / 20 €'],['Destino de las recompradas','Cancelación']])) ,
b('Un reparto puede competir con una necesidad urgente','Antes de devolver caja conviene comprobar pagos próximos y recursos para mantener el negocio. Conservar una reserva puede tener sentido cuando hay incertidumbre o vencimientos; acumularla sin propósito también tiene un coste de oportunidad. Para juzgar a la dirección revisa qué prometió, cuánto gastó y qué consiguió con el tiempo. Un beneficio por acción mayor no basta si se consiguió sacrificando liquidez o pagando demasiado por las recompras.',q('Una empresa simulada dispone de 100 € y debe pagar 90 € mañana, sin cobros previstos. Propone recomprar 50 €. ¿Qué problema ves?','La recompra dejaría insuficiente caja para el compromiso inmediato.','No hay problema si aumenta el beneficio por acción.','Quedarían 50 € frente a un pago de 90 €. La liquidez debe comprobarse antes.','Relaciona el gasto propuesto con el calendario de obligaciones.'))
],ex('Mismo presupuesto para recomprar',['Precio menor','Permite adquirir más acciones, pero todavía hay que juzgar su valor y la caja necesaria.'],['Precio mayor','Retira menos acciones; que una recompra exista no prueba que sea una buena inversión.']));

add(19,'lvmh','una buena empresa puede tener muchos precios','LVMH publicó ventas de aproximadamente 84.700 millones de euros en 2024.', ['Separar precio, valor contable y valor estimado.','Interpretar un rango sin tratarlo como una certeza.'],[
b('Conocer una marca no determina cuánto pagar','El precio es lo que el mercado pide por la acción. El valor contable procede del balance. El valor estimado es una conclusión que depende de hipótesis sobre lo que recibirá el propietario y de los riesgos. Pueden ser distintos sin que exista un error de cálculo. La calidad del negocio importa, pero una compra también depende del precio. Este caso no calcula un precio objetivo real de LVMH.',q('Una empresa simulada tiene productos excelentes, pero no has estudiado sus resultados ni el precio que piden. ¿Puedes concluir que comprarla conviene?','No; conocer la calidad no basta para valorar lo que pagas.','Sí; cualquier precio es razonable si la marca es buena.','Una buena experiencia como cliente no sustituye el análisis del negocio y del precio.','Distingue admirar un producto de valorar una inversión.')),
b('El precio por acción no mide por sí solo el tamaño','Una acción de precio pequeño no es necesariamente barata: quizá existen muchas acciones, o cada una representa menos derechos sobre el negocio. Para comparar valoraciones necesitas una magnitud económica coherente. Las estimaciones también deben admitir incertidumbre. La tabla muestra un rango ficticio: pagar menos que el valor central no elimina pérdidas posibles. Para medir una caída porcentual, divide la pérdida en euros entre el precio pagado y multiplica por cien.',n('Simulación: compras a 40 €. El valor central estimado es 50 €, pero acabas vendiendo a 35 €, sin otros cobros ni costes. ¿Qué porcentaje pierdes sobre la compra?',12.5,'%','Pierdes 5 € sobre 40 €: 5 ÷ 40 × 100 = 12,5 %. Estar por debajo del valor central estimado no evitaba este escenario.','Utiliza el precio pagado como base y el precio de venta del escenario.'),table([['Valor estimado desfavorable / central / favorable','35 € / 50 € / 65 €'],['Precio supuesto de compra','40 €']])) ,
b('La incertidumbre debe acompañar a la cifra','Un rango obliga a reconocer que ventas, márgenes o continuidad del negocio pueden evolucionar de varias formas. No tiene sentido presentar el valor central con aparente exactitud y ocultar que pequeños cambios lo alteran mucho. El valor de liquidación, por su parte, depende de vender activos y pagar obligaciones; no es el mismo enfoque que mantener el negocio funcionando. La elección del método debe responder a la realidad que intentas analizar.',m('Relaciona cada expresión de una ficha simulada.',[['Cotización observada','Precio de mercado'],['Activos contables menos pasivos','Patrimonio contable'],['Resultado de hipótesis de futuro','Valor estimado']],'Las tres cifras responden a preguntas distintas.','Pregunta cómo se ha obtenido cada importe.'))
],ex('¿Qué cambia si el valor es un rango?',['Solo mirar el centro','Puedes olvidar que el escenario desfavorable podría quedar por debajo del precio.'],['Leer también los extremos','Ves qué hipótesis sostienen la valoración y cuánto margen existe si fallan.']));

add(20,'inditex','del negocio entero a cada acción','El informe de Inditex de 2024 presenta por separado acciones, deuda financiera y recursos de caja.', ['Construir el puente entre valor de empresa y accionistas.','Distinguir caja disponible y recursos necesarios para operar.'],[
b('No todos los proveedores de dinero tienen el mismo derecho','La capitalización es el precio por acción multiplicado por las acciones existentes. El valor de empresa, o EV, suele representar la actividad antes de repartir su valor entre accionistas y financiadores. En un puente sencillo se añade deuda y se resta caja disponible para pasar de capitalización a EV. Los ajustes exactos dependen de qué incluye la medida operativa y de otras obligaciones. No mezcles definiciones de empresas diferentes sin revisarlas.',m('Relaciona los conceptos de una valoración simplificada.',[['Precio por acción por número de acciones','Capitalización'],['Valor de la actividad antes del reparto financiero','Valor de empresa'],['Préstamos menos caja elegible','Deuda neta']],'La coherencia del puente importa más que memorizar una sigla.','Distingue el conjunto de la actividad de la parte de los accionistas.')),
b('Resta obligaciones y añade la caja que corresponde','Si partes del valor de la actividad, debes restar lo debido a financiadores y añadir recursos no incluidos en esa actividad que pertenezcan a los accionistas. En este ejemplo no hay minoritarios, arrendamientos ni otros ajustes. Toda la caja indicada es excedentaria y está disponible. Explicitar esas condiciones permite hacer una cuenta pequeña sin convertir una simplificación en una regla válida para cualquier balance real.',n('Simulación: actividad valorada en 500 €, deuda de 100 €, caja excedentaria de 40 € y 20 acciones. ¿Qué valor resulta por acción?',22,'€ por acción','Valor de accionistas: 500 − 100 + 40 = 440. Por acción: 440 ÷ 20 = 22 €.','Haz primero el puente y después divide entre acciones.'),table([['Valor de actividad / deuda','500 € / 100 €'],['Caja excedentaria / acciones','40 € / 20']])) ,
b('No toda caja es un excedente repartible','Una parte del dinero puede necesitarse para salarios, proveedores o garantías. También puede estar restringida o pertenecer parcialmente a otros accionistas de una filial. Sumar toda la caja sin revisar su función puede sobrevalorar lo disponible para el propietario de la matriz. Del mismo modo, si el valor operativo incluye toda una filial, hay que considerar la parte que pertenece a terceros. La suma de componentes exige mantener el mismo perímetro.',q('El valor de actividad de una simulación ya incluye el efectivo necesario para operar. ¿Debes añadir de nuevo ese mismo efectivo?','No; hacerlo contaría dos veces el mismo recurso.','Sí; toda línea llamada caja debe sumarse siempre.','Los ajustes dependen de lo que ya está incluido en la valoración inicial.','Comprueba el perímetro antes de sumar.'))
],ex('Dos cajas con distinta función',['Excedente disponible','Puede añadirse si no estaba incluido en el valor de la actividad y pertenece al accionista.'],['Caja necesaria ya incluida','Añadirla otra vez duplicaría el recurso valorado.']));

add(21,'boeing','más acciones, una parte distinta','Boeing anunció en octubre de 2024 una oferta de acciones ordinarias y otra de títulos preferentes convertibles.', ['Calcular cómo una emisión cambia la participación.','Distinguir beneficio total, BPA y dilución potencial.'],[
b('La empresa recibe recursos, el accionista cambia de porcentaje','Emitir acciones puede aportar financiación, pero también aumenta el número de participaciones entre las que se distribuyen derechos. Si no compras parte de las nuevas, tu porcentaje puede disminuir aunque conserves todas tus acciones. Eso es dilución de participación. No demuestra por sí solo destrucción de valor: importa qué recibe la empresa y cómo lo utiliza. La operación real de Boeing sirve de contexto; los números que siguen son ficticios.',q('Una empresa simulada emite nuevas acciones por dinero. Conservas las tuyas, sin acudir a la emisión. ¿Qué puede ocurrir?','Tu porcentaje baja aunque no hayas vendido ninguna acción.','Tu porcentaje permanece siempre igual porque mantienes el mismo número.','El denominador aumenta cuando aparecen nuevas acciones.','Compara tus acciones con el nuevo total.')),
b('Cuenta también los derechos que pueden convertirse','El beneficio por acción, o BPA, divide el beneficio atribuible a accionistas ordinarios entre un número de acciones definido para el período. El básico utiliza el promedio correspondiente; el diluido considera ciertos derechos potenciales de conversión cuando producen dilución. No basta mirar las acciones al último día para reconstruir un promedio anual. Nuestra cuenta de participación se realiza en un instante posterior a la emisión, por lo que utiliza el total final.',n('Simulación: tienes 10 de 100 acciones. Se emiten 25 nuevas y no compras ninguna. ¿Qué porcentaje posees después?',8,'%','10 ÷ 125 × 100 = 8 %.','Aumenta el total de acciones, no las que tú conservas.'),table([['Tus acciones / total inicial','10 / 100'],['Nuevas acciones emitidas','25']])) ,
b('El beneficio total y el BPA pueden moverse distinto','Si el beneficio aumenta, pero el número de acciones aumenta todavía más, el beneficio por acción puede bajar. Una recompra puede producir el efecto inverso sin que crezca el negocio. Las opciones de empleados y los títulos convertibles también pueden influir en el futuro número de acciones. Al comparar períodos, revisa tanto el beneficio como las acciones y evita interpretar toda mejora del BPA como crecimiento de la actividad.',m('Relaciona estos cambios simulados con la revisión que requieren.',[['Más beneficio y muchas más acciones','Comprobar si sube o baja el BPA'],['Opciones que podrían ejercerse','Revisar dilución potencial'],['Emisión a mitad de año','Usar el promedio temporal para el BPA']],'Cada cambio afecta a la medida por acción de una forma distinta.','Separa el momento de la participación y el período del beneficio.'))
],ex('¿Para qué se usa el dinero de la emisión?',['Financiar un proyecto rentable','Puede aumentar el valor total; falta comparar esa mejora con la dilución y el precio emitido.'],['Cubrir pérdidas continuadas','Puede ganar tiempo, pero no resuelve por sí sola el problema del negocio.']));

add(22,'cat','un PER bajo puede esconder un pico','Los resultados de Caterpillar de 2024 distinguieron ventas, beneficio por acción y cifras ajustadas.', ['Calcular e interpretar el PER.','Detectar el efecto de un beneficio temporalmente elevado.'],[
b('El PER compara precio y beneficio por acción','El PER divide el precio de la acción entre el beneficio por acción de un período. Hay que indicar si ese beneficio es histórico o estimado, y si contiene ajustes. Un múltiplo bajo puede reflejar precio atractivo, pero también beneficios cerca de un máximo difícil de repetir. Una actividad cíclica cambia con la demanda y la inversión de sus clientes. No usaremos una cotización real ni emitiremos una recomendación sobre Caterpillar.',m('Relaciona cada cálculo con lo que utiliza.',[['Precio dividido por BPA del último ejercicio','PER histórico'],['Precio dividido por BPA previsto','PER estimado'],['BPA dividido por precio','Rendimiento del beneficio, inverso del PER']],'El período y el sentido de la división cambian la interpretación.','Localiza qué dato es una previsión.')),
b('Mantener el precio no mantiene el múltiplo','Si el precio no cambia y baja el beneficio por acción, el PER sube. Eso puede ocurrir cuando termina un año especialmente favorable. Para comparar empresas cíclicas conviene revisar varios períodos y entender qué parte del beneficio podría repetirse. Un beneficio normalizado es una estimación de una situación más representativa; no es una cifra oficial ni una garantía. En la tabla planteamos dos beneficios alternativos para el mismo precio.',n('Simulación: precio de 60 €, BPA excepcional de 10 € y BPA normalizado supuesto de 5 €. ¿Qué PER resulta usando el normalizado?',12,'veces','60 ÷ 5 = 12 veces. Con el beneficio excepcional habría sido 6 veces.','Elige el BPA que pide la pregunta.'),table([['Precio de la acción','60 €'],['BPA excepcional / normalizado supuesto','10 € / 5 €']])) ,
b('Un múltiplo aislado no compara riesgos','Dos empresas con el mismo PER pueden tener crecimiento, deuda y necesidades de inversión muy distintos. Además, un PER basado en pérdidas no funciona como una comparación ordinaria de años de beneficio: el signo negativo no significa una ganga. La cifra tampoco equivale al plazo exacto en que recuperarás tu dinero, porque los beneficios cambian y no se reparten necesariamente por completo. Debe leerse como una relación, acompañada de contexto.',q('Una empresa simulada muestra PER 5 justo después de un beneficio extraordinario por vender un edificio. ¿Qué revisarías?','El beneficio que quedaría sin esa venta y su capacidad de repetirse.','Comprar cuanto antes porque PER 5 garantiza recuperar el dinero en cinco años.','La venta puede inflar temporalmente el denominador.','Pregunta qué parte del beneficio corresponde al negocio habitual.'))
],ex('Mismo precio, dos beneficios',['Beneficio en un pico','El PER puede parecer pequeño porque el denominador está temporalmente elevado.'],['Beneficio representativo menor','El múltiplo aumenta y muestra una comparación diferente del mismo precio.']));

add(23,'bt','el EBITDA no paga toda la red','BT informó para 2023/24 de EBITDA ajustado de 8.100 millones de libras e inversión de 4.900 millones.', ['Emparejar correctamente valor y resultado.','Reconocer inversiones y costes que un múltiplo omite.'],[
b('Cada múltiplo deja cosas fuera','Un múltiplo relaciona una valoración con una medida del negocio. EV/EBITDA compara valor de empresa con un resultado anterior a intereses, impuestos y amortizaciones. Puede ayudar a comparar operaciones, pero deja fuera la inversión necesaria en equipos e infraestructura. Una red puede generar EBITDA y necesitar gran parte del efectivo para renovarse. Por eso un múltiplo aparentemente bajo no basta para concluir que el accionista recibirá mucha caja.',q('Una red simulada necesita sustituir equipos con frecuencia. ¿Qué falta al mirar solo EV/EBITDA?','Cuánto efectivo requiere mantener y ampliar esos equipos.','Nada: la amortización excluida significa que los equipos no cuestan dinero.','Excluir un gasto contable de una medida no elimina los pagos de inversión.','Distingue amortización contable e inversión pagada.')),
b('Haz coincidir el perímetro de la división','El valor de empresa abarca la actividad financiada por deuda y capital; por eso se compara con medidas operativas antes de intereses. La capitalización corresponde a accionistas y puede compararse con un resultado que ya descuenta la financiación, como el beneficio neto atribuible. En este ejercicio no hay ajustes de arrendamientos ni minoritarios. Mantener estas condiciones explícitas evita mezclar numeradores y denominadores de distinto alcance.',n('Simulación: EV de 600 € y EBITDA de 100 €. ¿Cuál es el múltiplo EV/EBITDA?',6,'veces','600 ÷ 100 = 6 veces. No se utiliza aquí la capitalización.','Usa las dos magnitudes del nombre del múltiplo.'),table([['Valor de empresa','600 €'],['EBITDA','100 €'],['Capitalización, dato no usado','400 €']])) ,
b('La elección depende de cómo funciona el negocio','En una empresa intensiva en activos puede ser útil mirar beneficio después de amortización y caja después de inversión. Un múltiplo de ventas ignora los márgenes; dos compañías que venden lo mismo pueden ganar cantidades muy distintas. El precio sobre valor contable también depende de la calidad de los activos y de la rentabilidad que producen. Elegir una medida exige saber qué refleja y qué deja pendiente de revisar.',m('Relaciona cada limitación con el múltiplo que la ilustra.',[['No distingue márgenes sobre iguales ventas','EV/ventas'],['No descuenta amortización en el resultado','EV/EBITDA'],['Depende del significado económico del patrimonio contable','Precio/valor contable']],'Ninguna medida sustituye estudiar el negocio y sus inversiones.','Mira el denominador y lo que omite.'))
],ex('Dos negocios con el mismo EBITDA',['Poca reposición de equipos','Puede conservar más caja, si los demás factores son iguales.'],['Reposición intensiva','Puede necesitar destinar mucho efectivo a mantener la actividad.']));

const comparableMedianTable=table([['Comparable A','50 veces'],['Comparable B','10 veces'],['Comparable C','16 veces'],['Comparable D','12 veces']]);
add(24,'costco','elegir comparables antes de promediar','El informe de Costco de 2024 separa ingresos por venta de mercancías e ingresos por cuotas de socios.', ['Seleccionar negocios comparables por su economía.','Usar una mediana sin convertirla en un precio automático.'],[
b('Compartir sector no basta para ser comparable','Dos empresas pueden vender alimentos y funcionar de manera distinta: una cobra cuotas, otra depende de márgenes por producto o de franquicias. También importan países, crecimiento, alquileres y deuda. Antes de comparar múltiplos, explica por qué las empresas se parecen en las características que generan resultados. Una lista larga de nombres poco relacionados puede dar una media precisa y una conclusión poco útil para la valoración.',u('Para comparar un comercio con cuotas, ¿qué dos características revisarías?', ['Peso y permanencia de los ingresos de socios','Márgenes y necesidades de inversión del modelo'],['Que el nombre tenga la misma longitud','Que la acción cueste aproximadamente lo mismo'],'Las características económicas importan más que parecidos superficiales.','Busca qué determina ingresos, gastos y capital necesario.')),
b('La mediana limita el peso de un extremo','Para calcular la mediana, primero ordena los datos de menor a mayor. Si hay un número impar de datos, toma el que queda en el centro. Si hay un número par, suma los dos centrales y divide entre dos: no hagas la media de toda la lista. Así un valor extremo pesa menos que en la media. Esto no corrige una mala selección de empresas: antes hay que alinear negocios, períodos y definiciones. Aquí suponemos comparables adecuados y solo practicamos cómo resumir sus múltiplos.',{...n('Los múltiplos simulados de cuatro comparables son 50, 10, 16 y 12 veces. Ordénalos y calcula su mediana.',14,'veces','Ordenados quedan 10, 12, 16 y 50. Los dos centrales son 12 y 16: (12 + 16) ÷ 2 = 14 veces. El 50 no entra en ese promedio.','Con cuatro datos, usa los que ocupan el segundo y el tercer lugar después de ordenar.'),figure:comparableMedianTable},comparableMedianTable) ,
b('Una diferencia puede tener una explicación económica','Que tu empresa cotice por debajo de la mediana puede reflejar menos crecimiento, más deuda o menor calidad de beneficios. También podría representar una oportunidad, pero hay que justificarlo con evidencia. No basta multiplicar automáticamente por la mediana del grupo. Los ajustes por diferencias deben ser comprensibles y no una forma de obtener el precio deseado. Conviene comprobar qué conclusión cambia al retirar un comparable poco adecuado.',q('Una empresa simulada tiene mucha más deuda y menor crecimiento que sus comparables. ¿Debe recibir automáticamente la mediana de su PER?','No; esas diferencias requieren análisis antes de trasladar el múltiplo.','Sí; pertenecer al mismo sector elimina cualquier diferencia.','La mediana resume el grupo, pero no corrige riesgos propios.','Compara las condiciones que pueden justificar el descuento.'))
],ex('¿Qué pasa si retiras un comparable extraño?',['La valoración cambia mucho','Puede haber dependencia excesiva de la selección; revisa la justificación del grupo.'],['La valoración cambia poco','La comparación es más estable, aunque todavía necesita hipótesis económicas razonables.']));

add(25,'msft','crecer también exige invertir','Microsoft describió en 2024 la expansión de infraestructura y centros de datos para sus servicios.', ['Construir un flujo operativo disponible para financiadores.','Relacionar crecimiento con inversión y circulante.'],[
b('Proyectar ventas es solo el primer paso','Una proyección de caja necesita explicar cómo las ventas se convierten en resultado y cuánto dinero exige producirlas. El flujo libre para la empresa, llamado FCFF, parte del beneficio operativo después de impuestos, suma amortización y resta inversión y aumentos de circulante. No descuenta intereses porque se calcula antes de repartir entre financiadores. Todos los importes que siguen son un modelo de práctica, no previsiones sobre Microsoft.',o('Ordena una proyección simplificada.', ['Estimar ventas y gastos de la actividad','Obtener beneficio operativo después de impuestos','Ajustar amortización, inversión y circulante para llegar al flujo'],'La cuenta conecta actividad, resultado y necesidades de efectivo.','No saltes de ventas directamente a caja libre.')),
b('Suma lo no pagado y resta lo que sí consume caja','La amortización reduce beneficio, pero no representa una nueva salida de efectivo en ese período, por lo que se añade al pasar a caja. La inversión pagada sí se resta. Un aumento del circulante consume recursos, por ejemplo al financiar más facturas pendientes de cobro. La tabla ya proporciona beneficio operativo después de impuestos, de modo que no tienes que calcular otra tasa ni volver a restar el impuesto.',n('Modelo simulado: beneficio operativo después de impuestos 40 €, amortización 10 €, inversión 25 € y aumento de circulante 5 €. ¿Cuál es el FCFF?',20,'€','40 + 10 − 25 − 5 = 20 €.','La amortización se suma; inversión y aumento del circulante se restan.'),table([['Beneficio operativo después de impuestos','40 €'],['Amortización / inversión','10 € / 25 €'],['Aumento de circulante','5 €']])) ,
b('El crecimiento necesita recursos coherentes','Si proyectas más ventas, pregunta si harán falta equipos, personal, existencias o crédito a clientes. Puede existir capacidad libre, pero hay que explicarlo; no es razonable suponer crecimiento ilimitado sin revisar la inversión. El flujo para el accionista, FCFE, además tiene en cuenta la financiación que corresponde a esa parte. Mezclar uno con una tasa o una valoración de otro perímetro produce resultados engañosos aunque las operaciones aritméticas sean correctas.',q('Una proyección simulada duplica ventas y mantiene inversión y recursos sin cambios, con instalaciones ya saturadas. ¿Qué revisarías?','La capacidad necesaria y los recursos que financiarían ese crecimiento.','Solo el número de decimales del beneficio.','La hipótesis operativa contradice la capacidad disponible.','Relaciona lo que se quiere vender con lo necesario para producirlo.'))
],ex('Más ventas con dos capacidades distintas',['Instalaciones con margen libre','Puede absorberse parte del crecimiento sin ampliar inmediatamente, si se justifica.'],['Instalaciones al límite','El crecimiento puede exigir inversión adicional o una alternativa de suministro.']));

add(26,'grid','descontar con una tasa coherente','National Grid describe en sus resultados 2024/25 el capital regulado sobre el que puede obtener un rendimiento autorizado.', ['Interpretar el descuento como coste de oportunidad.','Emparejar tasa, moneda y destinatario del flujo.'],[
b('Cobrar después no equivale a cobrar hoy','Descontar convierte un cobro futuro en una cantidad comparable hoy. La tasa expresa la rentabilidad exigida por tiempo y riesgo bajo unas hipótesis; no es una promesa de rendimiento. Si mantienes iguales el cobro futuro y el plazo, exigir más rentabilidad significa estar dispuesto a pagar menos hoy por ese mismo cobro. Por eso, una tasa de descuento mayor produce un valor presente menor, y una menor lo aumenta. Una actividad regulada puede tener reglas de remuneración, pero su accionista sigue afrontando riesgos. Practicaremos esta relación con supuestos ficticios.',q('Dos cobros simulados iguales llegan dentro de un año. Para uno se exige más rentabilidad por mayor riesgo. ¿Cuál tiene menor valor presente?','El que se descuenta a una tasa mayor.','El que se descuenta a una tasa menor.','Una exigencia mayor reduce lo que se pagaría hoy por el mismo cobro futuro.','Mantén fijo el cobro y cambia solo la tasa.')),
b('Aplica la tasa al período correcto','Para un cobro dentro de un año, el valor presente es el importe futuro dividido entre uno más la tasa anual. Con varios años, el divisor se compone durante ese plazo. La tasa debe ser coherente con moneda, inflación y riesgo del flujo; no conviene usar una tasa real con importes nominales sin ajustar. En esta cuenta tenemos un solo año y ambas magnitudes están en euros nominales.',n('Simulación: cobrarás 110 € dentro de un año y exiges un 10 % anual. ¿Cuál es su valor presente?',100,'€','110 ÷ 1,10 = 100 €.','Descuenta dividiendo; no restes el 10 % del importe futuro.'),table([['Cobro al terminar un año','110 €'],['Tasa anual supuesta','10 %']])) ,
b('La financiación también decide qué tasa corresponde','El coste del capital propio es la rentabilidad exigida por accionistas. El coste de deuda corresponde a los prestamistas. El WACC combina ambos con pesos y ajustes definidos y suele utilizarse con flujos para todos los financiadores. No intercambies tasas solo porque una sea menor y dé una valoración mayor. Debes mantener el mismo destinatario económico en flujo y tasa, además de revisar cómo has estimado cada componente.',m('Empareja los elementos de un modelo coherente.',[['Flujo solo para accionistas','Coste del capital propio'],['Flujo para deuda y accionistas','Coste medio ponderado del capital'],['Flujo nominal en euros','Tasa nominal coherente en euros']],'La tasa debe responder al mismo riesgo, moneda y perímetro del flujo.','Pregunta a quién corresponde el dinero calculado.'))
],ex('Mismo cobro, distinta rentabilidad exigida',['Tasa menor','El valor presente aumenta, manteniendo iguales el plazo y el cobro.'],['Tasa mayor','El valor presente disminuye; no cambia el importe nominal que se cobraría.']));

add(27,'visa','el futuro lejano pesa en el valor','Visa comunicó en su cuarto trimestre fiscal de 2024 indicadores separados de volumen de pagos y transacciones procesadas.', ['Comprender el valor terminal y sus límites.','Relacionar crecimiento perpetuo e inversión necesaria.'],[
b('Un modelo no puede detallar cada año para siempre','El valor terminal resume los flujos posteriores al período que proyectas año a año. Una fórmula habitual divide el flujo del primer año posterior entre tasa de descuento menos crecimiento estable. Supone que el negocio alcanza una situación sostenible. No permite prolongar indefinidamente una expansión extraordinaria. En este caso los números son hipótesis docentes, no una estimación de Visa ni de la evolución de sus pagos.',m('Relaciona cada parte del modelo.',[['Años calculados uno por uno','Período explícito'],['Resumen de los años siguientes','Valor terminal'],['Flujo del primer año posterior','Numerador de la perpetuidad creciente']],'El valor terminal representa una continuación, no una venta que necesariamente ocurrirá.','Ubica cada elemento en el tiempo.')),
b('La diferencia entre tasas cambia mucho el resultado','En la perpetuidad creciente la tasa de descuento debe superar al crecimiento. Si se acercan demasiado, el valor se vuelve muy sensible a pequeños cambios. El importe obtenido corresponde al final del período explícito y después debe descontarse hasta hoy. Aquí pedimos solo el valor en ese momento, para no mezclar dos operaciones. Usaremos un flujo que ya incluye la reinversión necesaria para sostener su crecimiento supuesto.',n('Simulación: flujo del primer año posterior de 10 €, tasa de descuento del 10 % y crecimiento estable del 2 %. ¿Cuál es el valor terminal al final del período explícito?',125,'€','10 ÷ (0,10 − 0,02) = 125 €. Falta descontarlo si queremos traerlo a hoy.','Convierte los porcentajes a decimales y resta las tasas.'),table([['Flujo del primer año posterior','10 €'],['Descuento / crecimiento estable','10 % / 2 %']])) ,
b('Crecer exige sostener la actividad','Una hipótesis de crecimiento estable debe acompañarse de márgenes, capital y reinversión coherentes. No basta aumentar el crecimiento terminal dejando intacta toda la caja disponible. También puede usarse un múltiplo de salida, pero sigue siendo una hipótesis sobre lo que valdrá el negocio entonces. Conviene comparar métodos y comprobar cuánto de la valoración total depende del tramo lejano, porque esa parte suele ser especialmente incierta.',q('Un modelo simulado crece para siempre al 12 % y descuenta al 8 % con la fórmula de perpetuidad creciente. ¿Qué harías?','Revisar las hipótesis: esa fórmula requiere descuento mayor que crecimiento.','Interpretar el resultado negativo como una empresa muy barata.','La relación entre tasas incumple la condición del modelo.','Comprueba el signo y el significado del denominador.'))
],ex('Dos cambios en el crecimiento terminal',['Aumentarlo sin más inversión','Puede inflar la valoración si no se justifica cómo se sostiene.'],['Vincularlo a reinversión','Obliga a mostrar qué recursos quedan realmente disponibles tras financiar ese crecimiento.']));

add(28,'arm','poner precio a escenarios distintos','La operación propuesta entre NVIDIA y Arm terminó cancelándose en febrero de 2022; el acuerdo inicial no aseguraba su ejecución.', ['Construir escenarios coherentes y ponderados.','Distinguir probabilidad, sensibilidad y certeza.'],[
b('Un anuncio no equivale a un resultado confirmado','Un escenario describe un conjunto de supuestos compatibles: qué ocurre, cómo afecta a ingresos o costes y qué valor produciría. Si una operación requiere autorizaciones, conviene distinguir éxito y fracaso sin dar por cerrado lo que sigue pendiente. Una sensibilidad cambia una variable para ver su efecto; un escenario puede cambiar varias relacionadas. Practicaremos con una operación ficticia, sin estimar probabilidades históricas de la compra de Arm.',q('Una valoración simulada supone simultáneamente que la adquisición se cancela y que se obtienen todas sus sinergias. ¿Qué falla?','Los supuestos del escenario son incompatibles.','Nada: sumar hipótesis favorables siempre mejora un análisis.','Las ventajas de una integración no deben mantenerse si el escenario excluye integrarla.','Pregunta si las hipótesis pueden ocurrir juntas.')),
b('Una media ponderada no describe un desenlace único','Ponderar consiste en multiplicar cada valor por su probabilidad y sumar. Las probabilidades deben completar el cien por cien y tener una justificación. El resultado esperado no tiene por qué coincidir con ningún desenlace posible: es un resumen del conjunto. En la tabla las probabilidades son supuestos inventados para practicar; no se presentan como las expectativas que el mercado tuvo sobre la operación real.',n('Simulación: escenario A vale 80 € con probabilidad del 25 % y B vale 40 € con el 75 %. ¿Cuál es el valor esperado?',50,'€','80 × 0,25 + 40 × 0,75 = 50 €.','Pondera cada valor antes de sumarlos.'),table([['Escenario A','80 €; 25 %'],['Escenario B','40 €; 75 %']])) ,
b('El margen depende también de la calidad de las hipótesis','La diferencia entre precio y valor estimado puede servir de margen frente a errores, pero no repara una valoración construida con supuestos injustificados. Examina qué tendría que pasar para que el precio actual tuviera sentido: esa es una lectura inversa del modelo. También prueba qué variable cambia más la conclusión. Así puedes enfocar la investigación en la incertidumbre relevante, en lugar de añadir decimales al escenario central.',u('Tu valoración simulada depende casi por completo de una autorización pendiente. ¿Qué dos acciones mejoran el análisis?', ['Separar el escenario sin autorización','Explicar de dónde salen las probabilidades usadas'],['Aumentar decimales del precio objetivo','Eliminar el escenario adverso porque resulta incómodo'],'La incertidumbre principal debe aparecer en el modelo y en su justificación.','Trabaja sobre la dependencia del resultado, no sobre su presentación.'))
],ex('Dos conclusiones tras ponderar',['El promedio parece atractivo','Todavía puede existir una pérdida grande en el escenario adverso.'],['El promedio cambia mucho con la probabilidad','La investigación debe centrarse en esa hipótesis y evitar una falsa precisión.']));

add(29,'alphabet','un cambio contable puede elevar beneficio','Alphabet amplió en 2023 la vida útil estimada de servidores y determinados equipos a seis años, reduciendo el gasto de amortización.', ['Distinguir cambio de estimación y mejora operativa.','Buscar explicaciones antes de calificar una alerta como fraude.'],[
b('Repartir un coste de otra forma cambia el resultado anual','La amortización distribuye el coste de un activo a lo largo de su vida útil estimada. Si se alarga esa vida, puede bajar el gasto anual pendiente y subir el beneficio, sin que aumenten las ventas ni entre caja nueva ese día. El cambio puede tener fundamento técnico; no es una prueba automática de irregularidad. Lo importante es entender la causa, el efecto y si la estimación encaja con el uso real.',m('Relaciona los cambios del ejemplo con lo que implican.',[['Alargar la vida útil restante','Repartir el importe pendiente entre más años'],['Cobrar una factura de cliente','Aumentar caja por un cobro'],['Vender más servicios','Cambiar la actividad comercial']],'Un cambio de estimación no es lo mismo que un cobro o una nueva venta.','Identifica el mecanismo que afecta al resultado.')),
b('Trabaja con el importe que todavía queda por amortizar','Cuando cambia la estimación, interesa el valor pendiente y la vida que queda, no volver a repartir desde cero todo lo ya consumido. Para simplificar suponemos amortización lineal, sin valor residual ni deterioro. La tabla presenta un equipo ficticio con valor pendiente de 60 €. No intenta reproducir el cálculo exacto ni los equipos de Alphabet; permite comparar dos calendarios futuros del mismo importe.',n('Equipo simulado: quedan 60 € por amortizar. La vida restante pasa de 3 a 5 años. ¿Cuánto baja el gasto anual a partir de ahora?',8,'€ al año','Antes: 60 ÷ 3 = 20. Después: 60 ÷ 5 = 12. Baja 8 €.','Calcula ambos gastos anuales sobre el mismo importe pendiente.'),table([['Valor pendiente','60 €'],['Vida restante anterior / nueva','3 / 5 años'],['Método','Lineal, sin valor residual']])) ,
b('Una alerta sirve para formular una pregunta precisa','Si crecen mucho las facturas por cobrar frente a las ventas, podría estar empeorando el cobro o cambiando el calendario. Si suben existencias, puede haber preparación para crecer o mercancía difícil de vender. Ningún indicador aislado permite sentenciar. Revisa notas, evolución y explicaciones de la dirección, y contrástalas con caja y actividad. El objetivo es encontrar qué información falta y cuánto podría cambiar tu interpretación del beneficio.',q('El beneficio de una empresa simulada mejora por menor amortización, pero no cambian ventas ni cobros. ¿Cómo lo registrarías?','Como mejora contable explicada por una estimación, pendiente de evaluar su fundamento.','Como prueba suficiente de que el negocio vende mejor.','El origen de la mejora debe conservarse en el análisis.','No atribuyas al negocio un efecto que procede del reparto del coste.'))
],ex('Dos preguntas al leer la nota',['¿Ha entrado dinero nuevo?','Cambiar una vida útil no genera por sí mismo una entrada de caja.'],['¿Es razonable la nueva vida?','Debe contrastarse con el uso, renovación y obsolescencia de los equipos.']));

add(30,'bt','obligaciones que no son un préstamo','BT comunicó en marzo de 2024 un déficit de pensiones bajo IAS19 de 4.800 millones de libras.', ['Distinguir gasto contable, pago y obligación estimada.','Incorporar pensiones y divisas sin duplicar ajustes.'],[
b('Las pensiones también pueden exigir recursos futuros','Un compromiso de pensiones puede obligar a una empresa a realizar pagos futuros. Comparar obligaciones estimadas con activos del plan permite identificar un déficit bajo una definición contable. Ese importe depende de hipótesis como tasas y duración de pagos; no es idéntico a una factura exigible mañana. Para analizarlo hay que revisar tanto la estimación como el calendario de aportaciones acordadas y evitar confundirlo con deuda bancaria ordinaria.',q('Un déficit de pensiones simulado aumenta porque cambia una tasa de valoración. ¿Qué puedes afirmar sin más datos?','Cambió la estimación; hace falta revisar el efecto sobre aportaciones y caja.','La empresa pagó automáticamente todo ese aumento hoy.','Una variación contable no equivale por sí sola a una salida inmediata de efectivo.','Separa medición de obligación y calendario de pago.')),
b('Calcula primero la diferencia entre compromiso y recursos','Para simplificar un plan de pensiones, compararemos el valor estimado de pagos comprometidos con los activos destinados a cubrirlos. La diferencia positiva es déficit en este modelo. No usaremos esa cifra como si fuese la aportación del próximo año. Tampoco aplicaremos tipos fiscales reales: son supuestos de práctica para entender la obligación y los recursos disponibles, no instrucciones tributarias sobre una empresa o un país.',n('Plan simulado: obligaciones valoradas en 150 € y activos del plan de 120 €. ¿Cuál es el déficit?',30,'€','150 − 120 = 30 €. El pago anual necesario requiere otra información.','Resta los recursos del plan al compromiso estimado.'),table([['Obligaciones estimadas','150 €'],['Activos del plan','120 €'],['Aportación del próximo año','No indicada']])) ,
b('Impuestos y divisas también tienen más de una lectura','El gasto por impuestos del resultado puede diferir del efectivo pagado por diferencias temporales, que originan impuestos diferidos. Convertir cuentas de una filial a otra moneda puede cambiar importes publicados sin cambiar ventas en su moneda local. Estos efectos deben separarse del funcionamiento operativo. En una valoración revisa si ya se han incorporado en los flujos o en otros ajustes, para no restar dos veces la misma obligación.',m('Relaciona los conceptos del análisis.',[['Gasto fiscal reconocido pero pagado en otro momento','Diferencia entre resultado y caja fiscal'],['Misma venta extranjera convertida a menos euros','Efecto de conversión de moneda'],['Compromiso de pensiones superior a activos del plan','Déficit estimado del plan']],'Son efectos distintos que requieren datos y ajustes diferentes.','Pregunta si cambia el pago, la traducción de moneda o la obligación estimada.'))
],ex('¿Dónde incluyes una obligación?',['En los flujos futuros','Los pagos previstos reducen la caja en los años correspondientes.'],['Como ajuste separado','Hay que evitar restarla de nuevo si los mismos pagos ya están descontados en los flujos.']));

add(31,'bt','la deuda tiene fechas y condiciones','BT informó de deuda neta de 19.500 millones de libras al cierre de marzo de 2024.', ['Relacionar vencimientos y fuentes de liquidez.','Probar cobertura de intereses en un escenario adverso.'],[
b('La cifra total no revela cuándo habrá que pagar','Una deuda puede ser manejable a largo plazo y problemática si vence antes de que lleguen los recursos. Revisa calendario, tasa fija o variable y condiciones contractuales. La deuda neta resta determinada caja, pero no elimina la necesidad de pagar cada vencimiento. Refinanciar significa conseguir otra financiación para sustituir la que vence; depende de disponibilidad y condiciones, no de una decisión unilateral de la empresa.',o('Ordena una revisión de vencimientos simulados.', ['Identificar importes y fechas de devolución','Compararlos con caja y recursos comprometidos disponibles','Evaluar el déficit y las opciones de financiación'],'La necesidad de refinanciar surge después de comparar pagos y recursos.','Empieza por obligaciones concretas, no por suponer un nuevo préstamo.')),
b('La cobertura compara beneficio e intereses','Una medida sencilla de cobertura divide el beneficio operativo entre los intereses del período. Indica cuántas veces los cubre esa medida de resultado, pero no garantiza caja ni capacidad de devolver el principal. Para una prueba adversa cambia de forma explícita beneficio e intereses. En el modelo siguiente no hay ajustes contables, y el escenario ya incluye el efecto supuesto de una subida de costes financieros.',n('Escenario simulado adverso: beneficio operativo 30 € e intereses 10 €. ¿Cuántas veces cubre el beneficio operativo los intereses?',3,'veces','30 ÷ 10 = 3 veces. Aún queda revisar caja y devolución del principal.','Divide el resultado operativo entre el coste financiero.'),table([['Beneficio operativo adverso','30 €'],['Intereses adversos','10 €'],['Principal que vence','Se revisa por separado']])) ,
b('Las condiciones pueden importar antes del impago','Un covenant es una condición del préstamo, por ejemplo mantener una ratio dentro de un límite. Incumplirla puede exigir negociar o activar consecuencias contractuales aunque aún se paguen intereses. También importa qué acreedor cobra primero y qué activos sirven de garantía. No basta afirmar que la deuda es barata: hay que entender qué flexibilidad conserva la empresa cuando el negocio empeora y qué recursos realmente puede utilizar.',q('Una empresa simulada paga intereses, pero supera un límite de deuda de su contrato. ¿Qué procede?','Revisar las consecuencias contractuales y si necesita una dispensa o renegociación.','Ignorarlo mientras siga pagando intereses.','Cumplir pagos no sustituye cumplir las demás condiciones pactadas.','Lee el contrato completo, no solo el cupón.'))
],ex('Dos deudas con el mismo importe',['Vence pronto','Exige disponer de recursos o financiación a tiempo.'],['Vence más adelante','Da más tiempo, pero conserva riesgos de negocio y futuras condiciones de financiación.']));

add(32,'ge','separar negocios sin crear dinero de la nada','GE anunció para abril de 2024 la entrega de una acción de GE Vernova por cada cuatro de GE, conservando las acciones de GE Aerospace.', ['Interpretar una escisión y sus efectos sobre el accionista.','Evitar duplicar valor al sumar negocios y ajustar deuda.'],[
b('Una escisión reparte negocios entre sociedades','En una escisión, una parte del grupo pasa a una sociedad separada y los accionistas pueden recibir acciones de ella según una proporción. Tener más títulos distintos no significa automáticamente tener más riqueza: ahora los derechos están repartidos entre negocios separados. También hay que revisar qué activos, deuda y costes quedan en cada uno. El anuncio de GE ilustra la mecánica; los precios de la práctica son completamente imaginados.',q('Tras una escisión simulada recibes acciones de otra sociedad y conservas las anteriores. ¿Qué debes comparar?','El valor conjunto de las dos participaciones y sus nuevas condiciones.','Solo el número de títulos, porque tener más siempre implica ganar.','La separación modifica cómo se representa la propiedad, no crea automáticamente valor.','Suma derechos económicos, no simplemente papeles.')),
b('La suma de partes exige un puente completo','Valorar por suma de partes significa estimar cada actividad con un método adecuado y combinar los resultados. Si obtienes valores de actividad antes de financiación, todavía debes restar deuda neta y otros ajustes para llegar al accionista. No añadas después un negocio ya incluido en otra parte. En esta simulación todos los valores son de actividad, están en la misma fecha y no existen participaciones minoritarias.',n('Grupo simulado: actividad A vale 300 €, B vale 200 € y la deuda neta conjunta es 100 €. ¿Qué valor queda para sus accionistas?',400,'€','300 + 200 − 100 = 400 €.','Suma primero las actividades y resta la financiación que corresponde.'),table([['Actividad A / B','300 € / 200 €'],['Deuda neta total','100 €']])) ,
b('Adquirir y separar requieren mirar costes reales','En una adquisición, las sinergias son mejoras esperadas por combinar negocios, como reducir costes duplicados. Hay que compararlas con el precio adicional pagado y los costes de integración. En una separación puede ocurrir lo contrario: aparecen funciones que antes se compartían. Que suba el beneficio por acción tras una operación no demuestra creación de valor; depende del precio, la financiación y los riesgos asumidos para obtener ese aumento.',m('Relaciona cada elemento de una operación simulada.',[['Ahorro esperado al integrar dos almacenes','Sinergia'],['Gasto para trasladar sistemas y equipos','Coste de integración'],['Dos equipos de administración tras separarse','Posible coste adicional de la escisión']],'Los cambios organizativos pueden aportar ahorro o crear costes nuevos.','Distingue beneficios esperados de desembolsos necesarios.'))
],ex('Dos formas de mirar una separación',['Solo más acciones','No informa de si el valor total ha aumentado.'],['Negocios y obligaciones por separado','Permite evaluar qué se conserva, qué se recibe y qué costes aparecen.']));

add(33,'wells','lo que se premia cambia la conducta','El CFPB relacionó en su sanción a Wells Fargo de septiembre de 2016 los incentivos de ventas con aperturas de cuentas no autorizadas.', ['Evaluar incentivos y controles de gobierno.','Separar crecimiento medido y creación de valor sostenible.'],[
b('Una métrica puede empujar en la dirección equivocada','El gobierno corporativo reúne reglas, supervisión e incentivos con los que se dirige una empresa. Premiar una cifra sin comprobar su calidad puede estimular conductas que elevan el indicador y dañan clientes o accionistas. El hecho de Wells Fargo pertenece a 2016: aquí no afirmamos que describa su conducta actual. La práctica plantea contratos ficticios para estudiar cómo combinar objetivos de actividad con calidad, permanencia y controles.',u('Un banco simulado paga solo por cuentas abiertas. ¿Qué dos controles reducirían el incentivo a inflar la cifra?', ['Verificar autorización del cliente','Comprobar uso real y permanencia de las cuentas'],['Contar también las solicitudes rechazadas como ventas','Eliminar la revisión para abrir más rápido'],'La calidad y legitimidad de la actividad deben acompañar a su volumen.','Busca controles que comprueben que la venta representa un servicio real.')),
b('El derecho económico y el voto pueden diferir','Una compañía puede tener clases de acciones con distintos votos. Poseer un porcentaje del capital no garantiza el mismo porcentaje de poder de decisión. Para entender el control, calcula votos y revisa quién puede nombrar o supervisar a los responsables. La siguiente estructura es ficticia y no describe la de Wells Fargo. Su objetivo es mostrar cómo un grupo pequeño de acciones puede reunir una parte importante de los votos.',n('Estructura simulada: clase A tiene 80 acciones con un voto cada una; clase B tiene 20 con cinco votos cada una. ¿Qué porcentaje de los votos tiene B? Redondea a dos decimales.',55.56,'%','B reúne 100 votos de 180 totales: 100 ÷ 180 × 100 = 55,56 %.','Calcula votos por clase antes de obtener el porcentaje.'),table([['Clase A','80 acciones × 1 voto'],['Clase B','20 acciones × 5 votos']])) ,
b('La supervisión debe poder cuestionar a la dirección','Un consejo debe evaluar decisiones y riesgos, no limitarse a aprobar resultados vistosos. Revisa independencia, experiencia, operaciones con personas vinculadas y cómo se responde a fallos anteriores. Una operación vinculada es una transacción con alguien relacionado con quienes controlan o dirigen; puede ser legítima, pero requiere transparencia y condiciones justificables. La propiedad de acciones por directivos alinea algunos intereses, aunque no elimina todos los conflictos posibles.',q('Una empresa simulada compra un inmueble a su directivo sin explicar precio ni proceso de aprobación. ¿Qué falta?','Información sobre condiciones, conflicto de interés y supervisión independiente.','Nada, si el directivo también posee acciones.','La participación del directivo no elimina el conflicto en una operación con él.','Separa estar invertido de poder decidir una transacción propia.'))
],ex('Dos incentivos de ventas',['Premiar solo cantidad','Puede favorecer actividad aparente aunque su calidad sea baja.'],['Revisar calidad y permanencia','Ayuda a comprobar si la actividad crea relaciones útiles y sostenibles.']));

add(34,'arm','escribir qué te haría cambiar de opinión','La cancelación de la operación NVIDIA–Arm en 2022 muestra que una adquisición anunciada puede no completarse.', ['Formular una tesis comprobable.','Buscar evidencia contraria y actualizar supuestos.'],[
b('Una tesis explica una causa, no un deseo','Una tesis de inversión conecta un mecanismo del negocio con resultados futuros: por qué esperas que ocurra algo y qué datos lo apoyarían. Debe distinguir hechos de supuestos y no confundirse con decir que la acción subirá. Si depende de una autorización pendiente, ese supuesto debe quedar escrito. La historia real sirve para recordar que el desenlace no se conoce de antemano; no para fingir que era evidente para todos.',o('Ordena la construcción de una tesis simulada.', ['Describir el mecanismo que produciría la mejora','Identificar datos y supuestos necesarios','Escribir qué evidencia obligaría a revisarla'],'Una tesis verificable puede contrastarse después con hechos.','Primero explica la causa; después define cómo comprobarla.')),
b('Un indicador debe estar unido al supuesto','Elegir indicadores concretos evita que cualquier noticia se interprete como confirmación. Si tu hipótesis depende de conservar clientes, mide renovaciones y condiciones de pago; si depende de una autorización, sigue hitos regulatorios. Un precio que sube no demuestra que el mecanismo empresarial esté funcionando. La tabla es una tesis inventada: clasifica la evidencia según el supuesto escrito, sin decidir comprar o vender una acción real.',q('Tesis simulada: una mejora de beneficios exige integrar una adquisición que todavía requiere autorización. Se deniega definitivamente. ¿Qué corresponde?','Retirar del modelo las mejoras que dependían de esa integración y revisar la tesis.','Mantenerlas porque la tesis inicial era convincente.','La evidencia contradice un supuesto necesario, aunque puedan existir otras razones para estudiar la empresa.','Busca qué condición era imprescindible.'),table([['Supuesto necesario','Adquisición autorizada e integrada'],['Nueva evidencia','Denegación definitiva'],['Elemento afectado','Mejoras que dependían de integrar']])) ,
b('Cambiar de opinión puede ser una buena actualización','El sesgo de confirmación consiste en buscar o valorar más lo que apoya nuestras ideas. Para reducirlo, formula de antemano preguntas incómodas y busca información que podría refutarlas. También distingue error de proceso y resultado desafortunado: una decisión puede estar razonada y aun así perder dinero. Registrar probabilidades, dudas y fuentes permite revisar cómo pensabas antes, sin reescribir la historia después de conocer el desenlace.',m('Relaciona estas prácticas de investigación.',[['Buscar solo opiniones que coinciden contigo','Sesgo de confirmación'],['Guardar supuestos antes de conocer el resultado','Registro previo de la decisión'],['Actualizar al fallar una condición necesaria','Revisión de la tesis']],'La disciplina consiste en permitir que la evidencia cambie la conclusión.','Distingue defender una idea de comprobarla.'))
],ex('Aparece una noticia contraria',['Ignorarla por incomodidad','Conserva la opinión, pero impide aprender si falló un supuesto importante.'],['Contrastar su relevancia','Puede obligar a revisar la tesis o resultar secundaria; hay que explicar por qué.']));

add(35,'berkshire','una decisión encaja dentro de una cartera','Berkshire describe en su informe de 2023 negocios propios e inversiones en valores, con exposiciones económicas diferentes.', ['Dimensionar posiciones según riesgo y necesidades.','Definir seguimiento y motivos de revisión antes de actuar.'],[
b('Tener una idea no decide cuánto dinero dedicarle','El tamaño de una posición depende de la incertidumbre, la concentración existente y los usos previstos del dinero. Una convicción fuerte no elimina el riesgo de equivocarse. Antes de comprar, mira qué otras posiciones sufrirían por la misma causa y qué pérdida podrías absorber. Este caso utiliza una cartera personal ficticia; no reproduce la de Berkshire ni propone un porcentaje adecuado para todos los inversores.',q('Ya tienes gran exposición a un sector y estudias otra empresa del mismo sector. ¿Qué debes evaluar antes de fijar su peso?','La exposición conjunta y el efecto de un problema compartido.','Solo lo convincente que parece la nueva idea por separado.','El riesgo se añade a una cartera existente, no a una hoja vacía.','Suma dependencias económicas, no solo nombres.')),
b('El peso cambia aunque no hagas operaciones','Una posición puede aumentar su peso porque sube más que el resto, aunque no compres acciones nuevas. Para medirlo usa valores actuales y el total actual de la cartera. No confundas un peso mayor con una nueva aportación. Revisar no obliga a vender: permite comprobar si la concentración sigue encajando con los límites y necesidades que habías definido, considerando costes y consecuencias de cualquier operación.',n('Cartera simulada: una posición vale ahora 400 € y el resto 600 €. ¿Cuál es el peso actual de esa posición?',40,'%','400 ÷ (400 + 600) × 100 = 40 %.','El denominador incluye la posición y el resto.'),table([['Posición analizada','400 €'],['Resto de la cartera','600 €']])) ,
b('El seguimiento debe volver a la tesis','Define qué datos revisarás, cuándo y qué cambios serían relevantes. Una caída del precio puede ocurrir sin deterioro del negocio, mientras que una tesis puede romperse antes de que lo refleje la cotización. Entre los motivos de venta pueden estar una tesis invalidada, necesidades de liquidez o una valoración que ya no compensa el riesgo. Registrar el motivo concreto ayuda a distinguir una decisión razonada de una reacción impulsiva.',u('¿Qué dos notas sirven para revisar una decisión simulada dentro de seis meses?', ['Los supuestos de negocio que justificaban la compra','Los hechos que obligarían a reducir o cerrar la posición'],['Solo el máximo precio que llegó a marcar','Solo la frase me gustaba la empresa'],'El diario debe permitir contrastar el razonamiento, no solo recordar una sensación.','Guarda criterios que puedan comprobarse después.'))
],ex('Dos causas de revisión',['Cambio de precio sin nueva información','Invita a revisar valoración y exposición, sin asumir automáticamente que la tesis cambió.'],['Fallo de un supuesto central','Exige reconsiderar el negocio aunque el precio todavía no se haya movido.']));

add(36,'cat','un pedido no es una máquina entregada','Caterpillar explicó que en 2024 el menor volumen redujo ventas, compensado parcialmente por precios favorables.', ['Conectar pedidos, capacidad y entregas industriales.','Evaluar costes de calidad y recursos para producir.'],[
b('Sigue el recorrido físico del producto','En una industria, un pedido expresa demanda, pero todavía puede requerir fabricación, entrega y cobro. La capacidad limita cuánto se puede producir; su utilización mide qué parte se está usando. Una cartera de pedidos elevada no elimina retrasos, cancelaciones ni problemas de proveedores. Para entender la actividad separa pedidos recibidos, unidades fabricadas y unidades entregadas. Las cantidades de este caso son una fábrica ficticia inspirada en estas preguntas industriales.',m('Relaciona cada indicador industrial.',[['Unidades que clientes han encargado y faltan por entregar','Cartera de pedidos'],['Máximo producible con los recursos definidos','Capacidad'],['Producción real dividida entre capacidad','Utilización']],'Demanda y producción son etapas distintas del recorrido.','Pregunta si el dato se refiere a encargos, límite o actividad real.')),
b('Una capacidad alta no garantiza producción útil','La utilización compara producción con capacidad bajo una definición concreta. Si aparecen defectos, no todas las unidades fabricadas pueden venderse. Si hay un cuello de botella, ampliar otra parte de la fábrica quizá no aumenta la salida final. En esta simulación la capacidad se mide en unidades terminadas por mes y todas las producidas son vendibles. Así podemos calcular utilización sin mezclar calidad, inventario o plazos de entrega.',n('Fábrica simulada: capacidad de 200 máquinas mensuales y producción de 150. ¿Qué porcentaje de capacidad utiliza?',75,'%','150 ÷ 200 × 100 = 75 %.','Divide producción real entre capacidad del mismo período.'),table([['Capacidad mensual','200 máquinas'],['Producción mensual vendible','150 máquinas']])) ,
b('Resolver el cuello de botella antes de ampliar','El cuello de botella es la etapa que limita el conjunto. Si el montaje espera componentes, comprar otra máquina de pintura no resuelve necesariamente las entregas. También hay que financiar existencias y cobros pendientes mientras se produce. El servicio posventa puede aportar ingresos distintos de vender equipos nuevos, pero necesita personal y repuestos. Un análisis industrial conecta demanda, funcionamiento de fábrica y recursos financieros en lugar de extrapolar pedidos directamente a beneficio.',q('Simulación: la fábrica puede montar 100 unidades, pero solo recibe componentes para 60. ¿Qué investigarías antes de ampliar montaje?','El suministro del componente que limita la producción.','Comprar más capacidad de montaje como única respuesta.','La restricción está antes del montaje; ampliarlo no aumenta los componentes disponibles.','Localiza la etapa que fija el máximo real.'))
],ex('Dos motivos para no entregar un pedido',['Falta de demanda firme','Puede requerir revisar pedidos o cancelaciones.'],['Falta de componentes','Puede requerir resolver suministro y financiar el calendario de producción.']));

add(37,'inditex','abrir tiendas no explica todo el crecimiento','Inditex describe en 2024 un modelo que integra ventas en tiendas físicas y canales digitales.', ['Separar crecimiento comparable y nuevas aperturas.','Relacionar tráfico, conversión y cesta con ventas.'],[
b('El total puede crecer aunque cada local venda menos','Las ventas comparables intentan medir una base de tiendas semejante entre períodos; revisa siempre su definición. Las aperturas añaden locales y pueden elevar ventas totales mientras los existentes empeoran. También hay interacción con el canal digital: una devolución o una recogida puede pasar por tienda. Para entender el crecimiento, separa los motores sin sumar dos veces una misma compra. Los locales y visitantes de la práctica son inventados.',q('Una cadena simulada abre muchas tiendas y aumenta ventas totales, pero bajan las ventas de la base comparable. ¿Qué significa?','El crecimiento total no demuestra mejora de los locales comparables.','Todas las tiendas han vendido más necesariamente.','Las aperturas pueden compensar el deterioro de la base existente.','Distingue cambio de número de tiendas y rendimiento de las anteriores.')),
b('Convierte visitas en compras y después en euros','El tráfico cuenta visitantes, la conversión indica qué proporción compra y la cesta media cuánto gasta cada comprador. Multiplicar esos tres elementos proporciona ventas bajo esta simplificación. No llames clientes a todos los visitantes si solo una parte compra. Tampoco confundas una cesta mayor con más unidades: puede reflejar precio o mezcla. Aquí cada comprador realiza una compra, y no hay devoluciones ni impuestos que ajustar.',n('Tienda simulada: 200 visitantes, conversión del 25 % y cesta media de 20 €. ¿Cuántas ventas en euros genera?',1000,'€','200 × 0,25 = 50 compras; 50 × 20 = 1.000 €.','Calcula primero cuántos visitantes compran.'),table([['Visitantes','200'],['Conversión','25 %'],['Cesta media','20 €']])) ,
b('El crecimiento tiene costes y un período de maduración','Una nueva tienda puede tardar en alcanzar su nivel habitual de ventas mientras ya paga alquiler y personal. Una franquicia aporta otra estructura: el franquiciado asume determinados recursos y paga según contrato, por lo que sus ventas no equivalen necesariamente a ingresos del franquiciador. En comercio digital también pesan entrega, devoluciones y preparación de pedidos. El análisis debe llegar a la economía del canal, no detenerse en cuántos locales o visitas añade.',m('Relaciona la pregunta con el dato a revisar.',[['¿Rinden mejor las tiendas existentes?','Ventas de base comparable'],['¿Cuánto cuesta devolver y enviar pedidos?','Economía del canal digital'],['¿Cuándo cubre gastos una apertura?','Maduración del nuevo local']],'Cada motor de expansión exige una comprobación diferente.','Une la pregunta con el dato que realmente la responde.'))
],ex('Dos crecimientos del 10 %',['Más tráfico con conversión estable','Sugiere más oportunidades de compra, pero deben revisarse los costes para atraer visitas.'],['Más cesta con menos compras','Puede ocultar pérdida de clientes y requiere separar precio, unidades y mezcla.']));

add(38,'unilever','marca, precio y volumen en el supermercado','Unilever desglosó en sus resultados 2024 el crecimiento por precio y volumen y señaló diferencias entre categorías.', ['Analizar precio, volumen y mezcla en consumo.','Relacionar materias primas, distribución y publicidad con margen.'],[
b('Subir precios no tiene el mismo efecto en todas las categorías','Una marca de consumo compite por espacio en tienda y por la elección del comprador, incluidas alternativas de marca del distribuidor. Subir precios puede compensar costes, pero también reducir unidades o cambiar la mezcla vendida. Por eso conviene mirar volumen y margen junto al ingreso total. La práctica usa un producto ficticio y no atribuye a una marca real una elasticidad o una subida de tarifa determinada.',u('Suben las ventas en euros de una marca simulada después de aumentar precios. ¿Qué dos datos faltan para interpretar la mejora?', ['Cómo ha cambiado el número de unidades vendidas','Cómo han cambiado costes y margen'],['El número de letras de la marca','La cotización de una empresa sin relación'],'Más ingresos pueden coexistir con menos volumen o con costes mayores.','Busca qué hay detrás del total facturado.')),
b('El margen por unidad conecta precio y coste','El margen bruto unitario resta al precio el coste directo del producto vendido. No cubre todavía toda la publicidad, administración o distribución que pueda contabilizarse después. Un coste de materias primas menor puede ayudar, pero la empresa quizá traslade parte al cliente o lo dedique a promocionar. En este modelo usamos el mismo envase y cantidad, sin mezcla, y pedimos solo la variación del margen bruto por unidad.',n('Producto simulado: antes se vende a 5 € y cuesta 3 €. Después se vende a 5,50 € y cuesta 4 €. ¿Cuánto disminuye el margen bruto por unidad?',0.5,'€','Antes deja 2 €; después 1,50 €. Disminuye 0,50 €.','Calcula precio menos coste en ambos períodos.'),table([['Antes: precio / coste directo','5 € / 3 €'],['Después: precio / coste directo','5,50 € / 4 €']])) ,
b('La publicidad y la innovación deben producir resultados','Invertir en marca puede sostener distribución, preferencia y precio, pero gastar más no garantiza vender mejor. Una innovación puede atraer nuevos compradores o quitar ventas a otro producto propio: esto último se llama canibalización. Para evaluar el lanzamiento compara crecimiento del conjunto, costes y permanencia, no solo ventas del producto nuevo. El poder del distribuidor también importa si exige descuentos, mejores condiciones o sustituye espacio por su propia marca.',q('Un lanzamiento simulado vende 100 €, pero otro producto propio pierde 80 € por clientes que se trasladan. Antes de costes, ¿qué debes analizar?','El aumento conjunto de 20 €, además del margen y coste del lanzamiento.','Solo los 100 € del producto nuevo, como crecimiento totalmente adicional.','Parte de las ventas procede del propio catálogo anterior.','Mira el conjunto de la empresa, no solo la novedad.'))
],ex('Dos orígenes del crecimiento de un lanzamiento',['Nuevos compradores para la empresa','Puede añadir demanda que antes no captaba.'],['Traslado desde otro producto propio','Puede mejorar la mezcla, pero no toda la venta es crecimiento adicional.']));

add(39,'lvmh','la exclusividad también tiene una economía','LVMH señaló en sus resultados de 2024 diferencias geográficas relacionadas, entre otros factores, con gasto de viajeros en Europa y Japón.', ['Distinguir demanda por origen del cliente y lugar de compra.','Evaluar precio, distribución e inventario en lujo.'],[
b('Una venta en un país no identifica al comprador','En lujo, un cliente puede comprar durante un viaje. Por eso el lugar donde se registra la venta no explica por sí solo de dónde procede la demanda. Cambios de moneda, turismo y diferencias de precio pueden desplazar compras entre países. También importan el atractivo de la marca y la experiencia de tienda. No deduciremos nacionalidades a partir de una cifra regional: la práctica plantea datos agregados ficticios para separar estas preguntas.',m('Relaciona cada dato con la pregunta que responde.',[['País donde se vende la pieza','Dónde se registra la compra'],['Residencia del comprador','De dónde procede la demanda'],['Precio pagado por producto comparable','Cuánto se cobra por la pieza']],'Ubicación de la venta y origen del cliente son dimensiones distintas.','Piensa qué clasifica cada dato.')),
b('Precio y unidades deben leerse juntos','Una subida del precio medio puede convivir con menos unidades. Para valorar el efecto calcula ventas y margen, y pregunta si la estrategia conserva demanda y exclusividad. No hay que tratar toda caída de unidades como un error ni toda subida de precio como poder ilimitado. En la simulación vendemos un único producto sin cambios de calidad o mezcla, de modo que podemos observar claramente cómo se combinan precio y cantidad.',n('Modelo simulado: antes vende 100 piezas a 10 €; después 80 a 15 €. ¿Cuánto aumentan las ventas totales?',200,'€','Antes: 1.000 €. Después: 1.200 €. Aumentan 200 €, aunque se venden menos piezas.','Multiplica unidades por precio en cada período.'),table([['Período A','100 piezas × 10 €'],['Período B','80 piezas × 15 €']])) ,
b('Vender más hoy puede afectar al posicionamiento futuro','Los descuentos ayudan a mover inventario, pero si son frecuentes pueden cambiar lo que el comprador está dispuesto a pagar a precio completo. La distribución controlada busca cuidar experiencia y disponibilidad; también exige inversión y gastos. Un mercado de segunda mano puede aportar señales de interés, aunque no sustituye medir ventas y caja de la empresa. El reto consiste en conectar decisiones comerciales con su sostenibilidad, sin convertir exclusividad en una palabra que justifique cualquier resultado.',q('Una marca simulada liquida gran parte de su colección con descuentos repetidos. ¿Qué pregunta resulta más útil?','Si está resolviendo un exceso puntual o debilitando la venta futura a precio completo.','Cuántos seguidores tiene, como única explicación de su capacidad de precio.','El efecto sobre inventario y expectativas de precio puede ser distinto a corto y largo plazo.','Relaciona la liquidación de hoy con el comportamiento futuro del cliente.'))
],ex('Dos señales de crecimiento',['Más tiendas y capacidad','Puede ampliar acceso, pero exige inversión y coherencia con el posicionamiento.'],['Mayor demanda en la misma red','Puede mejorar productividad, aunque requiere comprobar origen y permanencia de la demanda.']));

add(40,'adobe','una suscripción debe conservar al cliente','Adobe explica que reconoce gran parte del ingreso de suscripciones durante el período en que presta el servicio.', ['Separar retención de clientes y de ingresos.','Relacionar adquisición, expansión y caja de una suscripción.'],[
b('Perder pocos clientes no implica conservar todos los ingresos','La retención de clientes cuenta cuántos siguen; la retención de ingresos mira cuánto pagan los clientes de una base previa. Esa cantidad puede crecer si contratan más o caer si reducen uso, incluso con pocos abandonos. Para medirla bien, no añadas ventas a clientes nuevos dentro de la base antigua. Este caso utiliza una pequeña empresa de software ficticia: no son métricas ni condiciones comerciales publicadas por Adobe.',q('Una base simulada conserva a todos los clientes, pero cada uno contrata la mitad del servicio. ¿Qué ocurre?','La retención de clientes es completa, pero cae el ingreso de esa base.','Los ingresos se mantienen porque no se ha marchado ningún cliente.','Contar clientes no mide cuánto compra cada uno.','Distingue número de contratos e importe pagado.')),
b('La expansión puede compensar bajas dentro de la base','Para calcular retención neta de ingresos parte de una base inicial y sigue solo a esos clientes. Resta bajas y reducciones, suma ampliaciones y divide entre el importe inicial. Un resultado superior al cien por cien indica que la expansión ha superado las pérdidas de esa base; no prueba que adquirir nuevos clientes sea barato. En la tabla todos los datos corresponden al mismo intervalo anual y a la misma base.',n('Base simulada: comienza con 100 € de ingreso anual. Pierde 10 € por bajas y añade 30 € por ampliaciones. Sin nuevos clientes, ¿cuál es la retención neta de ingresos?',120,'%','(100 − 10 + 30) ÷ 100 × 100 = 120 %.','Sigue a los clientes iniciales; no incorpores clientes nuevos.'),table([['Ingreso inicial de la base','100 €'],['Bajas / ampliaciones','10 € / 30 €'],['Clientes nuevos incluidos','Ninguno']])) ,
b('Crecer cuesta dinero antes de recuperarlo','El coste de adquirir clientes incluye recursos comerciales necesarios para conseguirlos. Su recuperación depende del margen que dejan y del tiempo que permanecen, no solo de ventas prometidas. Cobrar una anualidad anticipada puede ayudar a la caja, pero obliga a prestar servicio después. La remuneración con acciones puede reducir pagos inmediatos y aun así tener un coste económico por dilución. Evaluar software exige unir permanencia, costes, inversión y derechos del accionista.',m('Relaciona la pregunta con el concepto adecuado.',[['¿Cuánto gastamos en captar un cliente?','Coste de adquisición'],['¿Cuándo se recupera con su margen?','Plazo de recuperación'],['¿Qué servicio debemos tras cobrar por adelantado?','Obligación pendiente del contrato']],'Ingresos recurrentes y cobros anticipados no eliminan costes ni obligaciones.','Cada pregunta mira una etapa distinta de la relación con el cliente.'))
],ex('Dos crecimientos iguales en ingresos',['Ampliación de clientes existentes','Puede aprovechar relaciones previas; todavía hay que medir el coste de servir más.'],['Captación de clientes nuevos','Puede exigir gasto comercial y un período hasta recuperar esa inversión.']));

add(41,'airbnb','reservas no es lo mismo que ingresos','Airbnb publicó para 2024 reservas brutas de 81.784 millones de dólares e ingresos de aproximadamente 11.100 millones.', ['Distinguir volumen intermediado e ingreso de plataforma.','Analizar comisión y economía por operación.'],[
b('La plataforma no se queda todo lo que pasa por ella','Una plataforma conecta participantes y puede cobrar una comisión por facilitar la operación. El volumen bruto reúne importes negociados o reservados bajo una definición que puede incluir cantidades de terceros. Los ingresos propios son otra medida. La tasa de comisión relaciona ingresos con volumen, pero exige definiciones y períodos comparables. La tabla de práctica simplifica reservas y comisión sin impuestos ni cancelaciones; no calcula una tasa oficial de Airbnb.',m('Relaciona los importes de una plataforma simulada.',[['Importe completo de las reservas','Volumen intermediado'],['Parte cobrada por prestar el servicio de plataforma','Ingreso por comisión'],['Dinero que corresponde al anfitrión','Importe de un tercero']],'Mover dinero de terceros no lo convierte en ingreso propio.','Identifica quién tiene derecho a cada parte.')),
b('Más volumen puede dejar poco margen','Una comisión debe cubrir costes como pagos, soporte, incentivos o prevención de fraude. Si una promoción cuesta más que el margen incremental que genera, el volumen puede crecer sin mejorar el resultado. En esta operación ficticia definimos explícitamente qué se cobra y qué gastos se descuentan. El margen de contribución obtenido aún no cubre todos los costes fijos de la plataforma, así que no lo llamaremos beneficio neto.',n('Operación simulada: reserva de 100 €, comisión de la plataforma del 15 %, coste variable de 4 € e incentivo de 3 €. ¿Qué contribución deja a la plataforma?',8,'€','Comisión: 15 €. Contribución: 15 − 4 − 3 = 8 €.','Empieza por la comisión, no por todo el importe de la reserva.'),table([['Reserva / comisión','100 € / 15 %'],['Coste variable / incentivo','4 € / 3 €']])) ,
b('La red debe ser útil para ambos lados','Un efecto de red aparece cuando más participantes aumentan la utilidad para otros. Más oferta puede atraer demanda y viceversa, pero confianza, disponibilidad y calidad importan. Si los usuarios emplean varias plataformas, ese efecto puede ser menos exclusivo de lo que parece. El crecimiento debe medirse junto a repetición, satisfacción y economía por operación. Añadir participantes mediante descuentos no demuestra por sí solo una ventaja difícil de replicar.',q('Una plataforma simulada duplica reservas gracias a promociones, pero cada reserva pierde dinero antes de costes fijos. ¿Qué investigarías?','Si puede conservar actividad útil al reducir incentivos y mejorar la contribución.','Solo el volumen, porque toda red grande acaba siendo rentable.','El tamaño no resuelve automáticamente una economía por operación negativa.','Une crecimiento y coste de mantenerlo.'))
],ex('Dos maneras de presentar actividad',['Volumen de reservas','Mide actividad intermediada según su definición, no lo que la empresa se queda.'],['Ingreso y contribución','Permiten acercarse a lo que cobra por servir esa actividad y a sus costes variables.']));

add(42,'visa','el dinero pagado no es ingreso de la red','Visa informó en su cuarto trimestre fiscal de 2024 de aumentos del 8 % en volumen de pagos a moneda constante y del 10 % en transacciones procesadas.', ['Separar funciones e importes dentro de un pago.','Interpretar importe medio y exposición internacional.'],[
b('En un pago participan empresas con funciones distintas','El banco emisor presta servicio al titular; el adquirente trabaja con el comercio; la red facilita el intercambio de mensajes y reglas entre participantes. Un procesador realiza tareas técnicas que pueden integrarse en otras entidades. Autorización comprueba si la operación se acepta; compensación organiza lo que cada parte debe; liquidación mueve los fondos correspondientes. No toda empresa de pagos presta dinero ni asume los mismos riesgos de crédito.',o('Ordena las tres grandes fases de un pago con tarjeta.', ['Autorización de la operación','Compensación de importes entre participantes','Liquidación de los fondos'],'Primero se acepta la operación, después se calculan obligaciones y finalmente se liquidan.','Distingue aprobar, calcular y transferir.')),
b('Volumen y transacciones permiten leer la cesta de pago','El volumen de pagos suma dinero; las transacciones cuentan operaciones. Dividir volumen entre número de pagos da el importe medio bajo una misma definición. Si el número crece más deprisa que el volumen, el importe medio puede bajar. Esto no determina por sí solo los ingresos de una red, porque intervienen tarifas, servicios y mezcla geográfica. El ejemplo usa euros y operaciones simuladas, sin trasladar tarifas reales de Visa.',n('Red simulada: procesa 1.200 € en 60 pagos. ¿Cuál es el importe medio de un pago?',20,'€ por pago','1.200 ÷ 60 = 20 €.','Divide dinero total entre número de operaciones.'),table([['Volumen procesado','1.200 €'],['Número de pagos','60']])) ,
b('La mezcla de operaciones cambia la economía','Los pagos nacionales e internacionales pueden generar ingresos y costes diferentes. También importan fraude, devoluciones, incentivos y regulación. No atribuyas una mejora de ingresos solo al crecimiento de operaciones sin comprobar esta mezcla. Un negocio puede tener gran escala y aun así necesitar mantener seguridad y disponibilidad. Al analizar pagos, sigue qué servicio presta cada empresa y qué riesgo conserva, en lugar de agrupar bancos, redes y procesadores como si fueran idénticos.',q('Una red simulada procesa el mismo número de pagos, pero crece el peso de operaciones internacionales con otra tarifa. ¿Qué puede cambiar?','El ingreso medio por operación, aunque la cantidad de pagos sea igual.','Nada: iguales operaciones siempre producen iguales ingresos.','La mezcla y las condiciones económicas afectan al ingreso por operación.','No supongas que todas las transacciones son idénticas.'))
],ex('Dos métricas del mismo trimestre',['Más transacciones','Indica mayor número de operaciones bajo la definición usada.'],['Más volumen monetario','Indica más dinero pagado; puede cambiar por número de pagos o importe medio.']));

add(43,'nvda','diseñar chips no es fabricarlos','NVIDIA describe en su informe del ejercicio 2025 un modelo de diseño apoyado en proveedores para fabricación, ensamblaje y pruebas.', ['Distinguir eslabones de la cadena de semiconductores.','Relacionar rendimiento de fabricación y coste por chip útil.'],[
b('La cadena reparte recursos y riesgos','Una empresa puede diseñar chips y encargar su fabricación, mientras otra opera fábricas o suministra equipos para producirlos. El término fabless describe el modelo sin fabricación propia de obleas. No significa ausencia de inversión o de riesgo: hay diseño, compromisos y dependencia de proveedores. Para analizar el sector identifica primero qué vende la empresa, quién fabrica y dónde podría aparecer una restricción que afecte a entregas.',m('Relaciona las actividades de esta cadena simulada.',[['Define la arquitectura del chip','Diseño'],['Produce chips sobre obleas','Fabricación'],['Suministra máquinas para producirlos','Equipamiento de fábricas']],'Los eslabones necesitan capital y afrontan riesgos distintos.','Identifica el trabajo concreto, no solo la palabra semiconductores.')),
b('El coste importa por unidad aprovechable','El rendimiento de fabricación mide qué parte de las unidades producidas cumple las condiciones para venderse. Si disminuye, el coste de producir se reparte entre menos chips útiles. Eso puede encarecer el producto aunque la factura por lote no cambie. La simulación elimina diferencias entre chips y otros costes para mostrar este mecanismo; no describe el rendimiento de un proceso real ni datos de un fabricante concreto.',n('Lote simulado: cuesta 100 € y produce 100 chips, de los que 80 son vendibles. ¿Cuál es el coste de fabricación por chip vendible?',1.25,'€ por chip','100 ÷ 80 = 1,25 € por chip útil.','Reparte el coste entre chips vendibles, no entre todos los intentos.'),table([['Coste total del lote','100 €'],['Chips producidos / vendibles','100 / 80']])) ,
b('La capacidad y el inventario cambian con el ciclo','Los plazos para ampliar capacidad pueden ser largos. Si muchos participantes invierten a la vez y después se frena la demanda, puede aparecer exceso de oferta. Si falta una etapa de ensamblaje o un equipo esencial, disponer de diseño no asegura entregas. También importan concentración de clientes, restricciones comerciales e inventarios. El análisis debe seguir toda la cadena necesaria para vender, sin extrapolar un trimestre fuerte indefinidamente.',q('Una empresa simulada tiene pedidos y diseños listos, pero su único proveedor de encapsulado está saturado. ¿Qué riesgo domina?','Una restricción de suministro que puede retrasar entregas.','Falta de demanda, demostrada por tener pedidos.','El problema está en una etapa necesaria para completar el producto.','Localiza el paso que impide convertir pedidos en entregas.'))
],ex('Dos cambios con el mismo coste por lote',['Mejor rendimiento','Más unidades útiles reparten el mismo coste y reducen el coste por chip vendible.'],['Más defectos','Menos unidades útiles deben absorber el coste del lote.']));

add(44,'shell','el precio de venta puede venir del mercado','Shell incluye en su informe de 2024 sensibilidades del valor recuperable a hipótesis de precios de materias primas.', ['Relacionar precio, producción y costes en materias primas.','Separar sensibilidad y predicción histórica.'],[
b('Producir más no controla el precio recibido','En materias primas, los precios de mercado pueden mover mucho el resultado de una producción similar. El precio realizado puede diferir de una referencia por calidad, transporte, ubicación o contratos. El coste de extracción tampoco recoge necesariamente toda la inversión y obligaciones futuras. Una sensibilidad pregunta qué cambiaría bajo otra hipótesis; no predice cuándo ocurrirá. Nuestro modelo usa unidades ficticias, sin reproducir precios históricos del petróleo ni operaciones de Shell.',q('Una productora simulada mantiene producción y coste unitario, pero baja el precio de venta. ¿Qué debe revisarse primero?','Cómo cambia el margen por unidad y la caja disponible.','Solo la cantidad producida, porque el precio no afecta al resultado.','El mismo volumen puede dejar un margen muy distinto.','Relaciona precio realizado y coste de producir.')),
b('Aísla el efecto de una variación de precio','Si mantienes cantidad y costes iguales, la variación de precio multiplicada por unidades muestra el cambio de resultado antes de otros efectos. En la práctica no hay coberturas, impuestos, amortización ni variaciones de inventario; por eso la cuenta es directa. En una empresa real esas partidas y los contratos pueden modificar el impacto. La hipótesis explícita permite entender la sensibilidad sin confundirla con un pronóstico completo.',n('Simulación: se venden 100 unidades. El precio cae de 8 € a 6 € y los demás elementos permanecen iguales. ¿Cuánto disminuye el resultado por ese cambio?',200,'€','La caída es 2 € por unidad: 2 × 100 = 200 €.','Calcula el cambio unitario y multiplícalo por cantidad.'),table([['Unidades vendidas','100'],['Precio anterior / nuevo','8 € / 6 €'],['Otros costes y efectos','Sin cambios']])) ,
b('Un año fuerte no decide la capacidad de repartir siempre','Los recursos extra de un precio elevado pueden destinarse a deuda, inversiones o repartos. Si se comprometen gastos permanentes como si ese precio durara para siempre, un ciclo adverso puede tensar la caja. También hay que financiar mantenimiento, cierre de instalaciones y obligaciones ambientales. Las reservas no equivalen a efectivo inmediato: extraerlas exige tiempo, costes y permisos. Analiza escenarios de precio y disciplina de inversión a lo largo del ciclo.',m('Relaciona las preguntas de una productora simulada.',[['¿Cuánto cobra realmente por unidad?','Precio realizado'],['¿Qué inversión necesita para sostener producción?','Mantenimiento de capacidad'],['¿Qué pasaría con otro precio de mercado?','Sensibilidad de resultados']],'Las tres preguntas conectan ingresos, recursos y escenarios.','Distingue un dato observado de una hipótesis alternativa.'))
],ex('Dos usos de un año de precios altos',['Reducir obligaciones','Puede ampliar flexibilidad si después cae el precio.'],['Asumir gastos permanentes elevados','Puede aumentar vulnerabilidad si el ingreso extraordinario no se repite.']));

add(45,'grid','una red depende de reglas e inversión','National Grid define su base regulada como capital sobre el que se permite obtener un retorno, distinto del valor contable ordinario.', ['Entender base regulada y rendimiento permitido.','Conectar inversión, ejecución y cobertura de deuda.'],[
b('La regla de ingresos forma parte del negocio','Una infraestructura puede cobrar según regulación, contrato o exposición al mercado. En una red regulada, las reglas reconocen determinados activos y condiciones de remuneración. La base regulada no es simplemente el precio al que podrías vender la empresa. El rendimiento permitido tampoco equivale a dividendo garantizado: existen costes, financiación y exigencias de servicio. Para analizarla hay que conocer el marco y la forma en que la inversión entra en esa base.',m('Relaciona cada concepto con su función.',[['Capital reconocido para remuneración regulatoria','Base regulada'],['Condiciones que fijan ingresos permitidos','Marco de regulación'],['Resultado después de costes y financiación','Importe distinto del retorno regulado bruto']],'La fórmula regulatoria es parte del análisis, no el resultado final para el accionista.','Separa base, reglas e importe que finalmente queda.')),
b('Un retorno sobre activos no es todo el flujo disponible','Para una ilustración elemental multiplicaremos una base reconocida por una tasa permitida. Esto calcula solo ese componente de remuneración en nuestro modelo. Un sistema real puede añadir recuperación de inversiones, gastos y ajustes de incentivos, por lo que no debe trasladarse la fórmula aislada a toda la factura del cliente. Las cantidades y la tasa de esta práctica son hipotéticas y no representan el régimen aplicado a National Grid.',n('Red simulada: base reconocida de 200 € y componente de retorno permitido del 5 %. ¿Cuánto representa ese componente anual?',10,'€ al año','200 × 0,05 = 10 €. No es automáticamente el dividendo ni toda la facturación.','Multiplica la base por la tasa indicada.'),table([['Base regulada simulada','200 €'],['Tasa del componente estudiado','5 %']])) ,
b('Cobrar a largo plazo no elimina problemas de ejecución','Construir una red exige pagar antes de recibir todos los ingresos asociados. Retrasos y sobrecostes pueden afectar a la financiación, y no todo gasto tiene por qué reconocerse igual en la regulación. Revisa calendario, deuda y margen para cumplir pagos si la obra tarda más. En una concesión también importa cuándo termina el derecho de explotación y qué ocurre con el activo entonces; no supongas flujos eternos donde existe un contrato finito.',q('Una obra simulada se retrasa un año y la remuneración empieza al entrar en servicio. ¿Qué debe actualizarse?','El calendario de cobros y la financiación necesaria durante la demora.','Solo la fecha del folleto, manteniendo todos los cobros anteriores.','El retraso afecta al momento en que llegan recursos para atender pagos.','Conecta la puesta en servicio con el inicio de ingresos.'))
],ex('Dos avances de una inversión',['Obra pagada pero no operativa','Puede consumir caja antes de generar la remuneración prevista.'],['Obra reconocida y operativa','Puede empezar a contribuir según las reglas, descontando los costes y obligaciones correspondientes.']));

add(46,'svb','un banco necesita liquidez y capital','La revisión oficial de SVB de 2023 destacó depósitos concentrados, inversiones de vencimiento largo y deficiencias en la gestión de liquidez y tipos.', ['Distinguir liquidez, solvencia y margen de intereses.','Relacionar préstamos, depósitos y vencimientos.'],[
b('El banco debe atender compromisos con distintos plazos','Un banco recibe depósitos y utiliza recursos en préstamos o inversiones. Los depositantes pueden pedir dinero antes de que esos activos venzan. Liquidez significa poder atender pagos a tiempo; solvencia se refiere a absorber pérdidas y sostener obligaciones con recursos suficientes. Un banco puede tener activos valiosos y sufrir un problema de caja urgente. La práctica simplifica esa estructura sin reproducir el balance real de SVB ni sus condiciones actuales.',q('Un banco simulado posee activos a largo plazo, pero hoy no dispone del efectivo solicitado por depositantes. ¿Qué problema inmediato aparece?','Liquidez: debe obtener efectivo a tiempo.','Una prueba de que todos sus préstamos valen cero.','La falta de efectivo inmediato no permite concluir por sí sola que todos los activos carezcan de valor.','Distingue disponibilidad temporal y valor económico.')),
b('El margen de intereses no es beneficio neto','El ingreso neto por intereses resta lo pagado por financiación a lo cobrado por préstamos y otras posiciones. Para obtener un margen porcentual hay que indicar la base utilizada, normalmente activos medios que generan intereses. Después quedan costes, pérdidas crediticias e impuestos. En este ejercicio solo calcularemos la diferencia en euros; no aplicaremos una ratio sobre una base que no está indicada.',n('Banco simulado: cobra 15 € de intereses y paga 6 € a sus financiadores. ¿Cuál es su ingreso neto por intereses?',9,'€','15 − 6 = 9 €. Todavía no se han restado otros gastos ni pérdidas de crédito.','Resta intereses pagados a intereses cobrados.'),table([['Intereses cobrados','15 €'],['Intereses pagados','6 €'],['Otros gastos y pérdidas','No incluidos en esta cuenta']])) ,
b('El capital absorbe pérdidas, la liquidez paga salidas','Si préstamos pierden valor, las provisiones reconocen pérdidas esperadas según el marco aplicable y afectan al resultado y al capital. Si salen depósitos, importa la disponibilidad de efectivo y de financiación, además de qué activos pueden venderse y a qué precio. Tasas más altas pueden modificar ingresos, costes y valor de inversiones de manera diferente. Analizar un banco exige estudiar estas conexiones, no trasladar sin ajustes las ratios de una fábrica.',m('Relaciona cada situación bancaria simulada.',[['Aumentan pérdidas esperadas en préstamos','Riesgo de crédito'],['Muchos depositantes retiran a la vez','Presión de liquidez'],['Sube el coste de captar depósitos','Presión sobre margen de intereses']],'Un banco puede afrontar varios riesgos al mismo tiempo, por mecanismos distintos.','Identifica qué recurso o resultado se ve afectado primero.'))
],ex('Dos pruebas diferentes',['Salidas de depósitos','Estudia efectivo, activos disponibles y financiación bajo presión.'],['Pérdidas en préstamos','Estudia deterioro del activo y capacidad del capital para absorberlo.']));

add(47,'berkshire','cobrar primas no es ganar todo el dinero','Berkshire distingue en su informe de 2023 el resultado de suscripción de seguros del rendimiento de las inversiones.', ['Separar primas, siniestros y resultado asegurador.','Interpretar ratio combinado y obligaciones pendientes.'],[
b('La prima llega antes de conocer todos los costes','Una aseguradora cobra por asumir determinados riesgos y después paga siniestros y gastos según contratos. Parte de los pagos puede ocurrir mucho más tarde, de modo que recibir efectivo no significa poder repartirlo libremente. Las reservas representan estimaciones de compromisos pendientes. El dinero mantenido entre cobro y pago puede invertirse, pero sigue respaldando obligaciones. Separaremos el resultado del seguro y el de invertir esos recursos.',m('Relaciona los componentes de una aseguradora simulada.',[['Cobro por asumir la cobertura','Prima'],['Coste de daños cubiertos','Siniestros'],['Estimación de compromisos aún pendientes','Reservas']],'Cada componente tiene un momento y una función diferentes.','No confundas entrada de caja con ganancia disponible.')),
b('El ratio combinado resume la economía de suscribir','En seguros de daños, el ratio combinado relaciona siniestros y gastos con primas ganadas, bajo la definición utilizada. Primas ganadas son las correspondientes a cobertura ya prestada, no necesariamente todas las emitidas o cobradas. Un ratio inferior al cien por cien indica beneficio de suscripción antes de inversiones en este modelo; por encima indica pérdida. La tabla utiliza magnitudes compatibles del mismo período y no reproduce ratios reales de Berkshire.',n('Aseguradora simulada: primas ganadas de 100 €, siniestros de 65 € y gastos de 25 €. ¿Cuál es el ratio combinado?',90,'%','(65 + 25) ÷ 100 × 100 = 90 %.','Suma siniestros y gastos antes de dividir por primas ganadas.'),table([['Primas ganadas','100 €'],['Siniestros / gastos','65 € / 25 €']])) ,
b('Las estimaciones pueden cambiar después','Una reserva puede resultar insuficiente si el coste final de siniestros supera lo esperado. Por eso conviene revisar cómo evolucionan estimaciones de años anteriores, exposición a catástrofes y reaseguro. El reaseguro transfiere parte de determinados riesgos a otra aseguradora según contrato, a cambio de un coste. Las inversiones también deben ser coherentes con los pagos esperados: obtener rentabilidad no compensa automáticamente una estructura que no puede atender compromisos.',q('Una aseguradora simulada mejora el beneficio porque reduce reservas antiguas, sin cambiar primas ni nuevos siniestros. ¿Qué revisarías?','La justificación de la nueva estimación y su historial de acierto.','Concluir que vender nuevas pólizas se ha vuelto más rentable.','El efecto proviene de revisar compromisos anteriores, no necesariamente del negocio nuevo.','Localiza el año y el origen de la mejora.'))
],ex('Dos fuentes de beneficio',['Suscripción rentable','Las primas ganadas superan siniestros y gastos bajo la definición empleada.'],['Inversiones rentables','Los recursos invertidos generan resultado, pero pueden coexistir con pérdidas al suscribir seguros.']));

add(48,'prologis','ocupación, rentas y valor del inmueble','Prologis informó de ocupación media del 97,1 % en su cartera poseída y gestionada durante el cuarto trimestre de 2023.', ['Distinguir ocupación, cobro y resultado operativo inmobiliario.','Relacionar renta sostenible, tasa de capitalización y deuda.'],[
b('Estar alquilado no responde a todas las preguntas','La ocupación indica qué parte de los espacios está arrendada bajo una definición concreta. No prueba por sí sola que todos los inquilinos paguen a tiempo ni que las rentas cubran gastos. Revisa ubicación, contratos, vencimientos y costes de mantener el inmueble. Un promotor que vende edificios tiene una economía distinta de un propietario que cobra alquileres. En este caso estudiaremos un inmueble ficticio que se mantiene para alquilar.',q('Un edificio simulado está totalmente alquilado, pero varios inquilinos no pagan. ¿Qué dato falta para valorar su funcionamiento?','Cobros efectivos y calidad de los contratos, además de ocupación.','Ninguno: ocupar el espacio equivale siempre a pagar puntualmente.','La ocupación física o contractual y la cobrabilidad no son idénticas.','Distingue contrato firmado y efectivo recibido.')),
b('El NOI se calcula antes de financiar el inmueble','El ingreso operativo neto del inmueble, o NOI, resta determinados gastos operativos a las rentas, antes de deuda y otros conceptos cuya definición debe aclararse. La tasa de capitalización relaciona NOI sostenible y valor del activo. Si divides un NOI anual estable entre una tasa, obtienes una valoración simplificada del inmueble antes de deuda. No incluye por sí sola todas las inversiones futuras ni garantiza que pueda venderse a ese precio.',n('Inmueble simulado: NOI sostenible anual de 10 € y tasa de capitalización del 5 %. ¿Qué valor de activo implica este modelo simple?',200,'€','10 ÷ 0,05 = 200 €. Es valor antes de deuda bajo las hipótesis indicadas.','Convierte la tasa a decimal y divide.'),table([['NOI anual sostenible supuesto','10 €'],['Tasa de capitalización supuesta','5 %']])) ,
b('La deuda amplifica cambios en el valor del accionista','Si el inmueble cambia de valor y la deuda permanece, la diferencia afecta a la parte del propietario. Además, renovar contratos puede exigir incentivos, obras o períodos vacíos. Un NOI de un año excepcional no debe utilizarse como permanente sin ajustes. Para pasar al valor del accionista resta obligaciones y revisa recursos adicionales, evitando contar dos veces costes ya incluidos. La valoración combina contratos, estado del activo, financiación y supuestos de mercado.',m('Relaciona cada revisión inmobiliaria.',[['Fin del contrato del principal inquilino','Riesgo de renovación'],['Obras necesarias para volver a alquilar','Inversión y coste de reposición'],['Deuda que vence antes de renovar alquileres','Riesgo de financiación']],'Los ingresos contractuales no eliminan necesidades de obras y liquidez.','Ubica cada riesgo en contrato, activo o financiación.'))
],ex('Mismo NOI con dos tasas',['Tasa menor','Implica un valor de activo mayor en este modelo, si todo lo demás es igual.'],['Tasa mayor','Implica un valor menor; la deuda puede amplificar el efecto sobre el patrimonio del propietario.']));

add(49,'novo','un ensayo no es una venta aprobada','Novo Nordisk distinguió en su informe 2024 productos comercializados, autorizaciones y avances de ensayos, incluido REDEFINE 1 en fase 3a.', ['Separar investigación, autorización y comercialización.','Ponderar escenarios sin tratar un éxito clínico como seguro.'],[
b('Cada etapa responde a una pregunta diferente','Un medicamento en investigación necesita demostrar seguridad y eficacia bajo condiciones estudiadas, además de superar evaluaciones regulatorias antes de comercializarse según sus indicaciones. Completar un ensayo no equivale a obtener autorización ni a lograr determinadas ventas. Después importan acceso, precio, fabricación y competencia. Esta práctica estudia el proceso empresarial, sin evaluar tratamientos ni dar consejos médicos. Las probabilidades que usaremos son ficticias y no corresponden a ningún ensayo de Novo Nordisk.',o('Ordena estos hitos de un proyecto farmacéutico simplificado.', ['Obtener evidencia mediante ensayos','Solicitar y obtener la autorización necesaria','Comercializar conforme a la autorización y condiciones de acceso'],'La actividad comercial requiere superar etapas que no son intercambiables.','No trates terminar un estudio como si ya fuese una venta.')),
b('El valor esperado debe conservar el escenario de fracaso','Un proyecto puede tener valor positivo si funciona y generar costes si no lo hace. Para ponderarlo, multiplica cada desenlace por su probabilidad y suma, sin borrar el escenario negativo. También importa cuándo se pagan costes y cuándo llegan cobros. Aquí todos los valores ya están expresados en euros de hoy después de los costes correspondientes, para centrarnos únicamente en la ponderación y no duplicar inversiones.',n('Proyecto ficticio: valor neto de 100 € si tiene éxito, con probabilidad del 30 %, y −20 € si fracasa, con el 70 %. ¿Cuál es el valor esperado?',16,'€','100 × 0,30 + (−20) × 0,70 = 16 €.','Conserva el signo negativo del escenario de fracaso.'),table([['Éxito: valor neto / probabilidad','100 € / 30 %'],['Fracaso: valor neto / probabilidad','−20 € / 70 %']])) ,
b('La cartera de productos también concentra riesgos','Una empresa puede depender mucho de un medicamento, una patente, una fábrica o un país. Al terminar determinadas protecciones, la competencia puede cambiar precios y volumen, pero el efecto debe estudiarse según producto y mercado. Las licencias y adquisiciones añaden otra forma de acceder a proyectos, con pagos y compromisos específicos. Para una empresa que todavía no genera caja suficiente, calcula cuánto tiempo puede financiar investigación bajo distintos escenarios de gasto.',q('Una compañía ficticia depende de un producto y toda su proyección ignora la entrada prevista de competidores. ¿Qué falta?','Un escenario que estudie su efecto sobre precio, volumen y caja.','Solo una previsión más precisa del número de decimales de ventas.','La concentración hace relevante el cambio competitivo, aunque su impacto sea incierto.','Relaciona el principal ingreso con el riesgo que puede modificarlo.'))
],ex('Dos estados de un proyecto',['Ensayo completado','Aporta evidencia que debe analizarse; todavía pueden faltar evaluaciones y pasos comerciales.'],['Producto autorizado','Permite determinados usos y mercados, pero no garantiza demanda, acceso ni rentabilidad.']));

add(50,'ge','comparar negocios sin forzarlos al mismo molde','El plan de separación anunciado por GE en 2024 distinguía un negocio de aviación y otro de energía.', ['Elegir métricas coherentes con cada modelo de negocio.','Priorizar la información que más cambia la valoración.'],[
b('La comparación empieza por entender cómo gana cada uno','Un negocio de mantenimiento industrial, una red regulada y una plataforma no necesitan los mismos recursos ni afrontan idénticos riesgos. Compararlos exige traducir métricas a preguntas comunes: cuánto crecen, qué dejan, cuánto capital requieren y qué puede fallar. La separación de GE sirve como contexto para no tratar un grupo diverso como una única actividad uniforme. Los negocios A y B de la práctica son perfiles ficticios, no segmentos valorados de GE.',m('Relaciona cada pregunta con la métrica que mejor se aproxima.',[['¿Qué deja la actividad por cada euro vendido?','Margen operativo'],['¿Qué produce respecto al capital que utiliza?','Rendimiento sobre capital'],['¿Qué recursos quedan tras financiar inversión?','Flujo libre definido de forma coherente']],'Las métricas son complementarias y responden a preguntas distintas.','No busques un único número que resuelva todas las comparaciones.')),
b('Un beneficio mayor puede exigir mucho más capital','Para una comparación útil conserva la misma definición de beneficio y de capital. Un negocio con margen elevado puede necesitar grandes inversiones; otro con margen pequeño puede vender muchas veces sobre una base de activos reducida. No concluyas que una empresa es mejor solo por superar al resto en una columna. En la tabla usamos beneficio operativo después de impuestos y capital medio, sin ajustar riesgos diferentes que deberán evaluarse después.',n('Modelos simulados: A gana 20 € con 100 € de capital y B gana 30 € con 300 €. ¿En cuántos puntos porcentuales supera el ROIC de A al de B?',10,'puntos porcentuales','A: 20 %. B: 10 %. Diferencia: 10 puntos porcentuales.','Calcula ambos cocientes y resta porcentajes; no calcules un crecimiento relativo.'),table([['Modelo A: beneficio / capital medio','20 € / 100 €'],['Modelo B: beneficio / capital medio','30 € / 300 €']])) ,
b('La siguiente pregunta debe atacar la mayor incertidumbre','Después de comparar, identifica qué supuesto sostiene la conclusión y qué información puede cambiarla. Si la duda es cuánto capital requiere crecer, investiga proyectos y capacidad; si es la estabilidad de clientes, revisa contratos y permanencia. Una cifra temporalmente fuerte merece contrastarse con el ciclo. El objetivo final no es declarar un ganador universal, sino construir una decisión explicable, con riesgos, valoración y límites visibles para quien vuelva a leerla.',u('Tu comparación ficticia depende de que A crezca sin invertir más, pero no conoces su capacidad. ¿Qué dos pasos son pertinentes?', ['Revisar si existen recursos productivos libres','Simular cuánto cambia el valor si necesita inversión adicional'],['Dar por seguro el supuesto porque mejora el resultado','Cambiar de múltiplo hasta obtener el precio deseado'],'La investigación y el escenario deben centrarse en el supuesto que decide la conclusión.','Busca información capaz de cambiar tu valoración.'))
],ex('Dos formas de cerrar el análisis',['Elegir la mayor cifra aislada','Puede premiar tamaño, deuda o un pico temporal sin entender la economía.'],['Conectar métricas, riesgos y precio','Permite explicar qué se está pagando, qué se espera y qué falta comprobar.']));

if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){
 if(cases.length!==50)throw new Error('Expected 50 authored cases');
 fs.writeFileSync(path.join(root,'src/content/cases-stocks-v2.json'),JSON.stringify({cases},null,2)+'\n');
 fs.writeFileSync(path.join(root,'scripts/cases-authoring/stocks-sources.json'),JSON.stringify({checkedAt:'2026-10-09',method:'Fuentes primarias abiertas y apartados relevantes leídos mediante la herramienta web. Hechos históricos limitados al período indicado. Los ejemplos numéricos de los ejercicios son simulaciones explícitas, no series históricas ni previsiones de las compañías.',sources:Object.entries(sources).map(([key,[company,period,title,url,supportedFacts]])=>({key,company,period,title,url,supportedFacts,caseNumbers:cases.filter(c=>c.sources[0].url===url).map(c=>Number(c.id.split('-').at(-1)))}))},null,2)+'\n');
 console.log(`Written ${cases.length} stock study cases and ${Object.keys(sources).length} verified-source entries.`);
}
